-- Default-dormant, auditable filesystem-v1 -> S3 Blob namespace migration ledger.
--
-- Applying this migration does not freeze writers, copy bytes, rewrite a storage pointer, or
-- activate blob_storage_control. The one-shot coordinator must use DB time and move the singleton
-- through the guarded phases. `cutting_over` is deliberately transaction-local in normal use:
-- the same InnoDB transaction rewrites only inventory-authorized pointers, activates generation 1
-- of blob_storage_control, appends the committed receipt/event, and publishes `committed`.
-- A crash therefore leaves either the verified source projection or the complete active target.

CREATE TABLE IF NOT EXISTS blob_storage_migration_control (
  singleton_id               TINYINT UNSIGNED NOT NULL,
  control_generation         BIGINT UNSIGNED NOT NULL DEFAULT 0,
  migration_id               VARCHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  phase                      VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NULL,
  source_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  target_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NULL,
  target_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  rollback_window_ms         BIGINT UNSIGNED NULL,
  source_cleanup_delay_ms    BIGINT UNSIGNED NULL,
  cutover_not_before_db_ms   BIGINT NULL,
  source_cleanup_not_before_db_ms BIGINT NULL,
  inventory_entry_count      BIGINT UNSIGNED NOT NULL DEFAULT 0,
  inventory_root_sha256      CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  object_ack_count           BIGINT UNSIGNED NOT NULL DEFAULT 0,
  object_ack_root_sha256     CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  source_cleanup_ack_count   BIGINT UNSIGNED NOT NULL DEFAULT 0,
  source_cleanup_ack_root_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  target_cleanup_ack_count   BIGINT UNSIGNED NOT NULL DEFAULT 0,
  target_cleanup_ack_root_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  started_at_db_ms           BIGINT NULL,
  inventory_sealed_at_db_ms  BIGINT NULL,
  verified_at_db_ms          BIGINT NULL,
  completed_at_db_ms         BIGINT NULL,
  terminal_receipt_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  fleet_drained_evidence_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  evidence_sha256            CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  PRIMARY KEY (singleton_id),
  CONSTRAINT chk_blob_migration_control_singleton CHECK (singleton_id = 1),
  CONSTRAINT chk_blob_migration_control_phase CHECK (
    phase IN (
      'inactive','frozen','inventory_sealed','copying','verified','cutting_over',
      'committed','source_cleaned','abort_cleaning','aborted'
    )
  ),
  CONSTRAINT chk_blob_migration_control_state CHECK (
    (control_generation = 0 AND migration_id IS NULL AND phase = 'inactive'
      AND source_backend IS NULL AND source_namespace_sha256 IS NULL
      AND target_backend IS NULL AND target_namespace_sha256 IS NULL
      AND rollback_window_ms IS NULL AND source_cleanup_delay_ms IS NULL
      AND cutover_not_before_db_ms IS NULL AND source_cleanup_not_before_db_ms IS NULL
      AND inventory_entry_count = 0 AND inventory_root_sha256 IS NULL
      AND object_ack_count = 0 AND object_ack_root_sha256 IS NULL
      AND source_cleanup_ack_count = 0 AND source_cleanup_ack_root_sha256 IS NULL
      AND target_cleanup_ack_count = 0 AND target_cleanup_ack_root_sha256 IS NULL
      AND started_at_db_ms IS NULL AND inventory_sealed_at_db_ms IS NULL
      AND verified_at_db_ms IS NULL AND completed_at_db_ms IS NULL
      AND terminal_receipt_sha256 IS NULL
      AND fleet_drained_evidence_sha256 IS NULL AND evidence_sha256 IS NULL)
    OR
    (control_generation > 0
      AND migration_id REGEXP '^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$'
      AND source_backend = 'filesystem-v1'
      AND source_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND target_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND BINARY target_backend = BINARY CONCAT('s3-v1-', LEFT(target_namespace_sha256, 24))
      AND rollback_window_ms IS NOT NULL
      AND source_cleanup_delay_ms IS NOT NULL
      AND cutover_not_before_db_ms IS NOT NULL AND cutover_not_before_db_ms >= 0
      AND started_at_db_ms IS NOT NULL AND started_at_db_ms >= 0
      AND fleet_drained_evidence_sha256 REGEXP '^[0-9a-f]{64}$'
      AND evidence_sha256 REGEXP '^[0-9a-f]{64}$'
      AND (
        (phase = 'source_cleaned'
          AND source_cleanup_ack_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND target_cleanup_ack_count = 0 AND target_cleanup_ack_root_sha256 IS NULL)
        OR (phase = 'aborted'
          AND source_cleanup_ack_count = 0 AND source_cleanup_ack_root_sha256 IS NULL
          AND target_cleanup_ack_root_sha256 REGEXP '^[0-9a-f]{64}$')
        OR (phase NOT IN ('source_cleaned','aborted')
          AND source_cleanup_ack_count = 0 AND source_cleanup_ack_root_sha256 IS NULL
          AND target_cleanup_ack_count = 0 AND target_cleanup_ack_root_sha256 IS NULL)
      )
      AND (
        (phase = 'frozen' AND inventory_entry_count = 0
          AND inventory_root_sha256 IS NULL AND object_ack_count = 0
          AND object_ack_root_sha256 IS NULL AND inventory_sealed_at_db_ms IS NULL
          AND verified_at_db_ms IS NULL AND completed_at_db_ms IS NULL
          AND source_cleanup_not_before_db_ms IS NULL
          AND terminal_receipt_sha256 IS NULL)
        OR
        (phase IN ('inventory_sealed','copying')
          AND inventory_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND inventory_sealed_at_db_ms IS NOT NULL AND inventory_sealed_at_db_ms >= started_at_db_ms
          AND object_ack_count = 0 AND object_ack_root_sha256 IS NULL
          AND verified_at_db_ms IS NULL AND completed_at_db_ms IS NULL
          AND source_cleanup_not_before_db_ms IS NULL
          AND terminal_receipt_sha256 IS NULL)
        OR
        (phase IN ('verified','cutting_over')
          AND inventory_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND inventory_sealed_at_db_ms IS NOT NULL AND inventory_sealed_at_db_ms >= started_at_db_ms
          AND object_ack_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND verified_at_db_ms IS NOT NULL
          AND verified_at_db_ms >= inventory_sealed_at_db_ms
          AND completed_at_db_ms IS NULL
          AND source_cleanup_not_before_db_ms IS NULL
          AND terminal_receipt_sha256 IS NULL)
        OR
        (phase = 'abort_cleaning'
          AND inventory_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND inventory_sealed_at_db_ms IS NOT NULL AND inventory_sealed_at_db_ms >= started_at_db_ms
          AND object_ack_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND (verified_at_db_ms IS NULL OR verified_at_db_ms >= inventory_sealed_at_db_ms)
          AND completed_at_db_ms IS NULL
          AND source_cleanup_not_before_db_ms IS NULL
          AND terminal_receipt_sha256 IS NULL)
        OR
        (phase IN ('committed','source_cleaned')
          AND inventory_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND inventory_sealed_at_db_ms IS NOT NULL AND inventory_sealed_at_db_ms >= started_at_db_ms
          AND object_ack_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND verified_at_db_ms IS NOT NULL
          AND verified_at_db_ms >= inventory_sealed_at_db_ms
          AND completed_at_db_ms IS NOT NULL AND completed_at_db_ms >= verified_at_db_ms
          AND source_cleanup_not_before_db_ms IS NOT NULL
          AND source_cleanup_not_before_db_ms >= completed_at_db_ms
          AND terminal_receipt_sha256 REGEXP '^[0-9a-f]{64}$')
        OR
        (phase = 'aborted'
          AND inventory_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND inventory_sealed_at_db_ms IS NOT NULL AND inventory_sealed_at_db_ms >= started_at_db_ms
          AND object_ack_root_sha256 REGEXP '^[0-9a-f]{64}$'
          AND (verified_at_db_ms IS NULL OR verified_at_db_ms >= inventory_sealed_at_db_ms)
          AND completed_at_db_ms IS NOT NULL AND completed_at_db_ms >= inventory_sealed_at_db_ms
          AND source_cleanup_not_before_db_ms IS NULL
          AND terminal_receipt_sha256 REGEXP '^[0-9a-f]{64}$')
      ))
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE IF NOT EXISTS blob_storage_migration_inventory (
  migration_id               VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  entry_ordinal              BIGINT UNSIGNED NOT NULL,
  record_kind                VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  record_id                  VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  record_sub_id              BIGINT UNSIGNED NOT NULL DEFAULT 0,
  record_aux_id              BIGINT UNSIGNED NOT NULL DEFAULT 0,
  storage_key                VARCHAR(512) COLLATE utf8mb4_0900_as_cs NULL,
  source_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  storage_format             VARCHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  object_disposition         VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  expected_sha256            CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  expected_size_bytes        BIGINT UNSIGNED NULL,
  expected_content_type      VARCHAR(255) COLLATE utf8mb4_0900_as_cs NULL,
  source_upload_token_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  source_record_sha256       CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  entry_sha256               CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  created_at_db_ms           BIGINT NOT NULL,
  PRIMARY KEY (migration_id, entry_ordinal),
  UNIQUE KEY uk_blob_migration_inventory_record
    (migration_id, record_kind, record_id, record_sub_id, record_aux_id),
  KEY idx_blob_migration_inventory_storage (migration_id, storage_key, entry_ordinal),
  CONSTRAINT chk_blob_migration_inventory_kind CHECK (
    record_kind IN (
      'blob_object','blob_delete_intent','export_artifact','export_part',
      'export_snapshot_pin','export_delete_intent'
    )
  ),
  CONSTRAINT chk_blob_migration_inventory_disposition CHECK (
    object_disposition IN ('data','tombstone','absent','metadata')
  ),
  CONSTRAINT chk_blob_migration_inventory_digest CHECK (
    source_backend = 'filesystem-v1'
      AND source_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND target_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND BINARY target_backend = BINARY CONCAT('s3-v1-', LEFT(target_namespace_sha256, 24))
      AND source_record_sha256 REGEXP '^[0-9a-f]{64}$'
      AND entry_sha256 REGEXP '^[0-9a-f]{64}$'
      AND created_at_db_ms >= 0
      AND ((object_disposition = 'metadata' AND storage_key IS NULL
             AND storage_format IS NULL AND expected_sha256 IS NULL
             AND expected_size_bytes IS NULL AND source_upload_token_sha256 IS NULL)
        OR (object_disposition IN ('data','tombstone','absent') AND storage_key IS NOT NULL
             AND storage_format IS NOT NULL
             AND source_upload_token_sha256 REGEXP '^[0-9a-f]{64}$'
             AND ((object_disposition = 'data'
                    AND expected_sha256 REGEXP '^[0-9a-f]{64}$'
                    AND expected_size_bytes IS NOT NULL)
               OR (object_disposition = 'absent'
                    AND expected_sha256 IS NULL AND expected_size_bytes IS NULL
                    AND expected_content_type IS NULL)
               OR (object_disposition = 'tombstone'
                    AND ((expected_sha256 IS NULL AND expected_size_bytes IS NULL)
                      OR (expected_sha256 REGEXP '^[0-9a-f]{64}$'
                        AND expected_size_bytes IS NOT NULL))))))
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE IF NOT EXISTS blob_storage_migration_object_acks (
  migration_id               VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  storage_key                VARCHAR(512) COLLATE utf8mb4_0900_as_cs NOT NULL,
  object_disposition         VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  expected_sha256            CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  expected_size_bytes        BIGINT UNSIGNED NULL,
  expected_content_type      VARCHAR(255) COLLATE utf8mb4_0900_as_cs NULL,
  source_observed_kind       VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_observed_kind       VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_descriptor_sha256   CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  target_descriptor_sha256   CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  verified_at_db_ms          BIGINT NOT NULL,
  ack_sha256                 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  PRIMARY KEY (migration_id, storage_key),
  UNIQUE KEY uk_blob_migration_object_ack (migration_id, ack_sha256),
  CONSTRAINT chk_blob_migration_object_ack_disposition CHECK (
    object_disposition IN ('data','tombstone','absent')
  ),
  CONSTRAINT chk_blob_migration_object_ack_digest CHECK (
    target_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND BINARY target_backend = BINARY CONCAT('s3-v1-', LEFT(target_namespace_sha256, 24))
      AND ack_sha256 REGEXP '^[0-9a-f]{64}$'
      AND verified_at_db_ms >= 0
      AND ((object_disposition = 'data'
             AND source_observed_kind = 'data' AND target_observed_kind = 'data'
             AND expected_sha256 REGEXP '^[0-9a-f]{64}$'
             AND expected_size_bytes IS NOT NULL
             AND source_descriptor_sha256 REGEXP '^[0-9a-f]{64}$'
             AND target_descriptor_sha256 REGEXP '^[0-9a-f]{64}$')
        OR (object_disposition = 'tombstone'
             AND source_observed_kind IN ('missing','data','tombstone')
             AND target_observed_kind = 'tombstone'
             AND ((source_observed_kind = 'data'
                    AND source_descriptor_sha256 REGEXP '^[0-9a-f]{64}$')
               OR (source_observed_kind IN ('missing','tombstone')
                    AND source_descriptor_sha256 IS NULL))
             AND target_descriptor_sha256 IS NULL)
        OR (object_disposition = 'absent'
             AND source_observed_kind = 'missing' AND target_observed_kind = 'missing'
             AND expected_sha256 IS NULL AND expected_size_bytes IS NULL
             AND expected_content_type IS NULL
             AND source_descriptor_sha256 IS NULL AND target_descriptor_sha256 IS NULL))
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE IF NOT EXISTS blob_storage_migration_events (
  migration_id               VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  event_seq                  BIGINT UNSIGNED NOT NULL,
  control_generation         BIGINT UNSIGNED NOT NULL,
  event_type                 VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  from_phase                 VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  to_phase                   VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  inventory_entry_count      BIGINT UNSIGNED NOT NULL,
  inventory_root_sha256      CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  object_ack_count           BIGINT UNSIGNED NOT NULL,
  object_ack_root_sha256     CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  occurred_at_db_ms          BIGINT NOT NULL,
  evidence_sha256            CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  event_sha256               CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  PRIMARY KEY (migration_id, event_seq),
  UNIQUE KEY uk_blob_migration_event_sha (migration_id, event_sha256),
  CONSTRAINT chk_blob_migration_event_digest CHECK (
    control_generation > 0 AND occurred_at_db_ms >= 0
      AND evidence_sha256 REGEXP '^[0-9a-f]{64}$'
      AND event_sha256 REGEXP '^[0-9a-f]{64}$'
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE IF NOT EXISTS blob_storage_migration_receipts (
  migration_id               VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  receipt_kind               VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  control_generation         BIGINT UNSIGNED NOT NULL,
  source_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  rollback_window_ms         BIGINT UNSIGNED NOT NULL,
  source_cleanup_delay_ms    BIGINT UNSIGNED NOT NULL,
  cutover_not_before_db_ms   BIGINT NOT NULL,
  source_cleanup_not_before_db_ms BIGINT NULL,
  inventory_entry_count      BIGINT UNSIGNED NOT NULL,
  inventory_root_sha256      CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  object_ack_count           BIGINT UNSIGNED NOT NULL,
  object_ack_root_sha256     CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_cleanup_ack_count   BIGINT UNSIGNED NOT NULL,
  source_cleanup_ack_root_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  target_cleanup_ack_count   BIGINT UNSIGNED NOT NULL,
  target_cleanup_ack_root_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  fleet_drained_evidence_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  blob_control_evidence_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  occurred_at_db_ms          BIGINT NOT NULL,
  receipt_sha256             CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  PRIMARY KEY (migration_id, receipt_kind),
  UNIQUE KEY uk_blob_migration_receipt_sha (migration_id, receipt_sha256),
  CONSTRAINT chk_blob_migration_receipt_kind CHECK (
    receipt_kind IN ('committed','aborted','source_cleaned')
  ),
  CONSTRAINT chk_blob_migration_receipt_digest CHECK (
    control_generation > 0 AND source_backend = 'filesystem-v1'
      AND source_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND target_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND BINARY target_backend = BINARY CONCAT('s3-v1-', LEFT(target_namespace_sha256, 24))
      AND cutover_not_before_db_ms >= 0
      AND inventory_root_sha256 REGEXP '^[0-9a-f]{64}$'
      AND object_ack_root_sha256 REGEXP '^[0-9a-f]{64}$'
      AND fleet_drained_evidence_sha256 REGEXP '^[0-9a-f]{64}$'
      AND occurred_at_db_ms >= 0
      AND receipt_sha256 REGEXP '^[0-9a-f]{64}$'
      AND ((receipt_kind = 'source_cleaned'
             AND source_cleanup_ack_root_sha256 REGEXP '^[0-9a-f]{64}$'
             AND target_cleanup_ack_count = 0 AND target_cleanup_ack_root_sha256 IS NULL)
        OR (receipt_kind = 'aborted'
             AND source_cleanup_ack_count = 0 AND source_cleanup_ack_root_sha256 IS NULL
             AND target_cleanup_ack_root_sha256 REGEXP '^[0-9a-f]{64}$')
        OR (receipt_kind = 'committed'
             AND source_cleanup_ack_count = 0 AND source_cleanup_ack_root_sha256 IS NULL
             AND target_cleanup_ack_count = 0 AND target_cleanup_ack_root_sha256 IS NULL))
      AND ((receipt_kind IN ('committed','source_cleaned')
             AND blob_control_evidence_sha256 REGEXP '^[0-9a-f]{64}$')
        OR (receipt_kind = 'aborted' AND blob_control_evidence_sha256 IS NULL))
      AND ((receipt_kind = 'committed'
             AND source_cleanup_not_before_db_ms IS NOT NULL
             AND source_cleanup_not_before_db_ms >= occurred_at_db_ms)
        OR (receipt_kind = 'source_cleaned'
             AND source_cleanup_not_before_db_ms IS NOT NULL
             AND occurred_at_db_ms >= source_cleanup_not_before_db_ms)
        OR (receipt_kind = 'aborted' AND source_cleanup_not_before_db_ms IS NULL))
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE IF NOT EXISTS blob_storage_migration_source_cleanup_acks (
  migration_id               VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  storage_key                VARCHAR(512) COLLATE utf8mb4_0900_as_cs NOT NULL,
  object_disposition         VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_observed_kind       VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_descriptor_sha256   CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  cleaned_at_db_ms           BIGINT NOT NULL,
  ack_sha256                 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  PRIMARY KEY (migration_id, storage_key),
  UNIQUE KEY uk_blob_migration_source_cleanup_ack (migration_id, ack_sha256),
  CONSTRAINT chk_blob_migration_source_cleanup_ack CHECK (
    object_disposition IN ('data','tombstone','absent')
      AND source_backend = 'filesystem-v1'
      AND source_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND ((object_disposition = 'data'
             AND source_observed_kind = 'tombstone'
             AND source_descriptor_sha256 REGEXP '^[0-9a-f]{64}$')
        OR (object_disposition = 'absent' AND source_observed_kind = 'tombstone'
             AND source_descriptor_sha256 IS NULL)
        OR (object_disposition = 'tombstone' AND source_observed_kind = 'tombstone'))
      AND cleaned_at_db_ms >= 0
      AND ack_sha256 REGEXP '^[0-9a-f]{64}$'
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE IF NOT EXISTS blob_storage_migration_target_cleanup_acks (
  migration_id               VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  storage_key                VARCHAR(512) COLLATE utf8mb4_0900_as_cs NOT NULL,
  object_disposition         VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_backend             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_namespace_sha256    CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  cleanup_result             VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_observed_kind       VARCHAR(16) COLLATE utf8mb4_0900_as_cs NOT NULL,
  target_descriptor_sha256   CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  target_migration_owner_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  cleaned_at_db_ms           BIGINT NOT NULL,
  ack_sha256                 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  PRIMARY KEY (migration_id, storage_key),
  UNIQUE KEY uk_blob_migration_target_cleanup_ack (migration_id, ack_sha256),
  CONSTRAINT chk_blob_migration_target_cleanup_ack CHECK (
    object_disposition IN ('data','tombstone','absent')
      AND target_namespace_sha256 REGEXP '^[0-9a-f]{64}$'
      AND BINARY target_backend = BINARY CONCAT('s3-v1-', LEFT(target_namespace_sha256, 24))
      AND cleaned_at_db_ms >= 0
      AND ack_sha256 REGEXP '^[0-9a-f]{64}$'
      AND ((object_disposition = 'absent' AND cleanup_result = 'missing'
             AND target_observed_kind = 'missing'
             AND target_descriptor_sha256 IS NULL
             AND target_migration_owner_sha256 IS NULL)
        OR (object_disposition IN ('data','tombstone')
             AND cleanup_result = 'fenced_tombstone'
             AND target_observed_kind = 'tombstone'
             AND target_descriptor_sha256 IS NULL
             AND BINARY target_migration_owner_sha256 = BINARY SHA2(CONCAT(
               '["blob-storage-migration-target-owner-v1","',migration_id,
               '","',target_namespace_sha256,'","',storage_key,'"]'),256))
        OR (cleanup_result = 'preserved_conflict'
             AND target_observed_kind IN ('data','tombstone')
             AND (target_migration_owner_sha256 IS NULL
               OR target_migration_owner_sha256 REGEXP '^[0-9a-f]{64}$')
             AND ((target_observed_kind = 'data'
                    AND target_descriptor_sha256 REGEXP '^[0-9a-f]{64}$')
               OR (target_observed_kind = 'tombstone'
                    AND target_descriptor_sha256 IS NULL))))
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

INSERT INTO blob_storage_migration_control
  (singleton_id,control_generation,migration_id,phase,source_backend,target_backend,
   source_namespace_sha256,target_namespace_sha256,rollback_window_ms,
   source_cleanup_delay_ms,cutover_not_before_db_ms,
   source_cleanup_not_before_db_ms,inventory_entry_count,
   inventory_root_sha256,object_ack_count,object_ack_root_sha256,
   source_cleanup_ack_count,source_cleanup_ack_root_sha256,
   target_cleanup_ack_count,target_cleanup_ack_root_sha256,started_at_db_ms,
   inventory_sealed_at_db_ms,verified_at_db_ms,completed_at_db_ms,
   terminal_receipt_sha256,fleet_drained_evidence_sha256,evidence_sha256)
SELECT 1,0,NULL,'inactive',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,
       0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
 WHERE NOT EXISTS (
   SELECT 1 FROM blob_storage_migration_control WHERE singleton_id=1
 );

-- The control projection is permanent. New attempts may start only from inactive/aborted and must
-- use a fresh migration id and a monotonically increasing generation. All other updates are exact
-- phase transitions; no connection/session variable grants cutover authority.
DROP TRIGGER IF EXISTS trg_blob_mover_control_bi;
CREATE TRIGGER trg_blob_mover_control_bi BEFORE INSERT ON blob_storage_migration_control FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control singleton already exists';
DROP TRIGGER IF EXISTS trg_blob_mover_control_bi_guard_a;
CREATE TRIGGER trg_blob_mover_control_bi_guard_a BEFORE INSERT ON blob_storage_migration_control FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control singleton already exists';
DROP TRIGGER IF EXISTS trg_blob_mover_control_bd;
CREATE TRIGGER trg_blob_mover_control_bd BEFORE DELETE ON blob_storage_migration_control FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control cannot be deleted';
DROP TRIGGER IF EXISTS trg_blob_mover_control_bd_guard_a;
CREATE TRIGGER trg_blob_mover_control_bd_guard_a BEFORE DELETE ON blob_storage_migration_control FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control cannot be deleted';

DROP TRIGGER IF EXISTS trg_blob_mover_control_bu;
CREATE TRIGGER trg_blob_mover_control_bu BEFORE UPDATE ON blob_storage_migration_control FOR EACH ROW BEGIN IF NOT (OLD.singleton_id=1 AND NEW.singleton_id=1 AND (((OLD.phase IN ('inactive','aborted')) AND NEW.phase='frozen' AND NEW.control_generation=OLD.control_generation+1 AND NEW.migration_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_events e WHERE e.migration_id=NEW.migration_id) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=NEW.migration_id) AND NEW.source_backend='filesystem-v1' AND NEW.target_backend=CONCAT('s3-v1-',LEFT(NEW.target_namespace_sha256,24)) AND NEW.inventory_entry_count=0 AND NEW.inventory_root_sha256 IS NULL AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.started_at_db_ms IS NOT NULL AND NEW.inventory_sealed_at_db_ms IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase NOT IN ('inactive','aborted') AND NEW.control_generation=OLD.control_generation AND BINARY NEW.migration_id=BINARY OLD.migration_id AND BINARY NEW.source_backend=BINARY OLD.source_backend AND BINARY NEW.target_backend=BINARY OLD.target_backend AND BINARY NEW.target_namespace_sha256=BINARY OLD.target_namespace_sha256 AND NEW.cutover_not_before_db_ms=OLD.cutover_not_before_db_ms AND NEW.started_at_db_ms=OLD.started_at_db_ms AND ((OLD.phase='frozen' AND NEW.phase='inventory_sealed' AND NEW.inventory_entry_count=(SELECT COUNT(*) FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id) AND NEW.inventory_root_sha256 IS NOT NULL AND NEW.inventory_sealed_at_db_ms IS NOT NULL AND NEW.inventory_sealed_at_db_ms>=OLD.started_at_db_ms AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase='inventory_sealed' AND NEW.phase='copying' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase='copying' AND NEW.phase='verified' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_object_acks a WHERE a.migration_id=OLD.migration_id) AND NEW.object_ack_root_sha256 IS NOT NULL AND NEW.verified_at_db_ms IS NOT NULL AND NEW.verified_at_db_ms>=OLD.inventory_sealed_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition AND BINARY a.target_backend=BINARY i.target_backend AND BINARY a.target_namespace_sha256=BINARY i.target_namespace_sha256 AND a.expected_sha256<=>i.expected_sha256 AND a.expected_size_bytes<=>i.expected_size_bytes))) OR (OLD.phase='verified' AND NEW.phase='cutting_over' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)>=OLD.cutover_not_before_db_ms) OR (OLD.phase='cutting_over' AND NEW.phase='committed' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NOT NULL AND NEW.completed_at_db_ms>=OLD.verified_at_db_ms AND NEW.terminal_receipt_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_control c WHERE c.singleton_id=1 AND c.control_generation=1 AND BINARY c.storage_backend=BINARY OLD.target_backend AND BINARY c.namespace_sha256=BINARY OLD.target_namespace_sha256 AND BINARY c.evidence_sha256=BINARY (SELECT r.blob_control_evidence_sha256 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='committed' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256))) OR (OLD.phase='verified' AND NEW.phase='abort_cleaning' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control c WHERE c.singleton_id=1 AND c.control_generation=0)) OR (OLD.phase='abort_cleaning' AND NEW.phase='aborted' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NOT NULL AND NEW.completed_at_db_ms>=OLD.verified_at_db_ms AND NEW.terminal_receipt_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='aborted' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256)) OR (OLD.phase='committed' AND NEW.phase='source_cleaned' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms=OLD.completed_at_db_ms AND BINARY NEW.terminal_receipt_sha256=BINARY OLD.terminal_receipt_sha256 AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='source_cleaned') AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition))))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control transition is not permitted'; END IF; END;
-- A source-cleaned receipt is inserted while control is still committed, in the same transaction
-- that publishes source_cleaned. Bind it to the already-active generation-1 Blob control instead
-- of requiring the evidence column to be NULL.
DROP TRIGGER IF EXISTS trg_blob_mover_receipts_bi_guard_a;
DROP TRIGGER IF EXISTS trg_blob_mover_receipts_bi;
CREATE TRIGGER trg_blob_mover_receipts_bi_guard_a BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.occurred_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.rollback_window_ms=NEW.rollback_window_ms AND c.source_cleanup_delay_ms=NEW.source_cleanup_delay_ms AND c.cutover_not_before_db_ms=NEW.cutover_not_before_db_ms AND BINARY c.fleet_drained_evidence_sha256=BINARY NEW.fleet_drained_evidence_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND NEW.source_cleanup_not_before_db_ms=NEW.occurred_at_db_ms+NEW.source_cleanup_delay_ms AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_target_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.target_cleanup_ack_root_sha256 IS NOT NULL AND NEW.occurred_at_db_ms>=c.inventory_sealed_at_db_ms AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.source_cleanup_not_before_db_ms=c.source_cleanup_not_before_db_ms AND NEW.source_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.source_cleanup_ack_root_sha256 IS NOT NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.source_cleanup_not_before_db_ms AND NEW.blob_control_evidence_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;
CREATE TRIGGER trg_blob_mover_receipts_bi BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.occurred_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.rollback_window_ms=NEW.rollback_window_ms AND c.source_cleanup_delay_ms=NEW.source_cleanup_delay_ms AND c.cutover_not_before_db_ms=NEW.cutover_not_before_db_ms AND BINARY c.fleet_drained_evidence_sha256=BINARY NEW.fleet_drained_evidence_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND NEW.source_cleanup_not_before_db_ms=NEW.occurred_at_db_ms+NEW.source_cleanup_delay_ms AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_target_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.target_cleanup_ack_root_sha256 IS NOT NULL AND NEW.occurred_at_db_ms>=c.inventory_sealed_at_db_ms AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.source_cleanup_not_before_db_ms=c.source_cleanup_not_before_db_ms AND NEW.source_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.source_cleanup_ack_root_sha256 IS NOT NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.source_cleanup_not_before_db_ms AND NEW.blob_control_evidence_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;

DROP TRIGGER IF EXISTS trg_blob_mover_control_bu_guard_a;
CREATE TRIGGER trg_blob_mover_control_bu_guard_a BEFORE UPDATE ON blob_storage_migration_control FOR EACH ROW BEGIN IF NOT (OLD.singleton_id=1 AND NEW.singleton_id=1 AND (((OLD.phase IN ('inactive','aborted')) AND NEW.phase='frozen' AND NEW.control_generation=OLD.control_generation+1 AND NEW.migration_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_events e WHERE e.migration_id=NEW.migration_id) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=NEW.migration_id) AND NEW.source_backend='filesystem-v1' AND NEW.target_backend=CONCAT('s3-v1-',LEFT(NEW.target_namespace_sha256,24)) AND NEW.inventory_entry_count=0 AND NEW.inventory_root_sha256 IS NULL AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.started_at_db_ms IS NOT NULL AND NEW.inventory_sealed_at_db_ms IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase NOT IN ('inactive','aborted') AND NEW.control_generation=OLD.control_generation AND BINARY NEW.migration_id=BINARY OLD.migration_id AND BINARY NEW.source_backend=BINARY OLD.source_backend AND BINARY NEW.target_backend=BINARY OLD.target_backend AND BINARY NEW.target_namespace_sha256=BINARY OLD.target_namespace_sha256 AND NEW.cutover_not_before_db_ms=OLD.cutover_not_before_db_ms AND NEW.started_at_db_ms=OLD.started_at_db_ms AND ((OLD.phase='frozen' AND NEW.phase='inventory_sealed' AND NEW.inventory_entry_count=(SELECT COUNT(*) FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id) AND NEW.inventory_root_sha256 IS NOT NULL AND NEW.inventory_sealed_at_db_ms IS NOT NULL AND NEW.inventory_sealed_at_db_ms>=OLD.started_at_db_ms AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase='inventory_sealed' AND NEW.phase='copying' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase='copying' AND NEW.phase='verified' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_object_acks a WHERE a.migration_id=OLD.migration_id) AND NEW.object_ack_root_sha256 IS NOT NULL AND NEW.verified_at_db_ms IS NOT NULL AND NEW.verified_at_db_ms>=OLD.inventory_sealed_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition AND BINARY a.target_backend=BINARY i.target_backend AND BINARY a.target_namespace_sha256=BINARY i.target_namespace_sha256 AND a.expected_sha256<=>i.expected_sha256 AND a.expected_size_bytes<=>i.expected_size_bytes))) OR (OLD.phase='verified' AND NEW.phase='cutting_over' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)>=OLD.cutover_not_before_db_ms) OR (OLD.phase='cutting_over' AND NEW.phase='committed' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NOT NULL AND NEW.completed_at_db_ms>=OLD.verified_at_db_ms AND NEW.terminal_receipt_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_control c WHERE c.singleton_id=1 AND c.control_generation=1 AND BINARY c.storage_backend=BINARY OLD.target_backend AND BINARY c.namespace_sha256=BINARY OLD.target_namespace_sha256 AND BINARY c.evidence_sha256=BINARY (SELECT r.blob_control_evidence_sha256 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='committed' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256))) OR (OLD.phase='verified' AND NEW.phase='abort_cleaning' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control c WHERE c.singleton_id=1 AND c.control_generation=0)) OR (OLD.phase='abort_cleaning' AND NEW.phase='aborted' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NOT NULL AND NEW.completed_at_db_ms>=OLD.verified_at_db_ms AND NEW.terminal_receipt_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='aborted' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256)) OR (OLD.phase='committed' AND NEW.phase='source_cleaned' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms=OLD.completed_at_db_ms AND BINARY NEW.terminal_receipt_sha256=BINARY OLD.terminal_receipt_sha256 AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='source_cleaned') AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition))))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control transition is not permitted'; END IF; END;

-- Every evidence table is append-only. Duplicate/replayed inserts converge through primary or
