-- Inventory rows are admitted only while the exact attempt is frozen and each row must describe a
-- currently durable source projection. Tokens remain outside the ledger; only their SHA-256 is
-- retained. A later seal transition also proves that no eligible source row was omitted.
DROP TRIGGER IF EXISTS trg_blob_mover_inventory_bi_guard_a;
CREATE TRIGGER trg_blob_mover_inventory_bi_guard_a BEFORE INSERT ON blob_storage_migration_inventory FOR EACH ROW BEGIN DECLARE v_phase VARCHAR(32) DEFAULT 'invalid'; DECLARE v_migration_id VARCHAR(64) DEFAULT NULL; DECLARE v_source_backend VARCHAR(32) DEFAULT NULL; DECLARE v_source_namespace CHAR(64) DEFAULT NULL; DECLARE v_target_backend VARCHAR(32) DEFAULT NULL; DECLARE v_target_namespace CHAR(64) DEFAULT NULL; DECLARE v_started BIGINT DEFAULT NULL; SELECT phase,migration_id,source_backend,source_namespace_sha256,target_backend,target_namespace_sha256,started_at_db_ms FROM blob_storage_migration_control WHERE singleton_id=1 FOR SHARE INTO v_phase,v_migration_id,v_source_backend,v_source_namespace,v_target_backend,v_target_namespace,v_started; IF v_phase<>'frozen' OR NOT (BINARY NEW.migration_id=BINARY v_migration_id) OR NOT (BINARY NEW.source_backend=BINARY v_source_backend) OR NOT (BINARY NEW.source_namespace_sha256=BINARY v_source_namespace) OR NOT (BINARY NEW.target_backend=BINARY v_target_backend) OR NOT (BINARY NEW.target_namespace_sha256=BINARY v_target_namespace) OR NEW.created_at_db_ms<v_started OR NOT ((NEW.record_kind='blob_object' AND NEW.record_sub_id=0 AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM blob_objects b WHERE BINARY b.blob_id=BINARY NEW.record_id AND (b.state<>'deleted' OR EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL)) AND BINARY b.storage_backend=BINARY NEW.source_backend AND BINARY b.storage_key=BINARY NEW.storage_key AND BINARY b.storage_format=BINARY NEW.storage_format AND BINARY SHA2(b.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND ((NEW.object_disposition=(CASE WHEN b.state='deleted' THEN 'tombstone' WHEN b.sha256 IS NULL AND b.size_bytes IS NULL AND b.uploaded_at_ms IS NULL THEN 'absent' ELSE 'data' END) AND NEW.expected_sha256<=>(CASE WHEN b.sha256 IS NULL THEN NULL ELSE LOWER(HEX(b.sha256)) END) AND NEW.expected_size_bytes<=>b.size_bytes AND NEW.expected_content_type<=>b.content_type) OR (b.state='staging' AND b.sha256 IS NULL AND b.size_bytes IS NULL AND b.content_type IS NULL AND b.uploaded_at_ms IS NULL AND b.ready_at_ms IS NULL AND b.delete_after_ms IS NULL AND b.deleted_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL) AND NEW.object_disposition='data' AND NEW.expected_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.expected_size_bytes IS NOT NULL)))) OR (NEW.record_kind='blob_delete_intent' AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM blob_delete_outbox o JOIN blob_objects b ON b.blob_id=o.blob_id WHERE BINARY o.blob_id=BINARY NEW.record_id AND o.generation=NEW.record_sub_id AND o.completed_at_ms IS NULL AND BINARY b.storage_backend=BINARY NEW.source_backend AND BINARY b.storage_key=BINARY NEW.storage_key AND BINARY b.storage_format=BINARY NEW.storage_format AND BINARY SHA2(b.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='tombstone' AND NEW.expected_sha256<=>(CASE WHEN b.sha256 IS NULL THEN NULL ELSE LOWER(HEX(b.sha256)) END) AND NEW.expected_size_bytes<=>b.size_bytes AND NEW.expected_content_type<=>b.content_type)) OR (NEW.record_kind='export_artifact' AND NEW.record_sub_id=0 AND NEW.record_aux_id=0 AND NEW.object_disposition='metadata' AND EXISTS (SELECT 1 FROM user_export_artifacts a WHERE BINARY a.artifact_id=BINARY NEW.record_id AND a.state<>'deleted' AND BINARY a.storage_backend=BINARY NEW.source_backend)) OR (NEW.record_kind='export_part' AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY NEW.record_id AND p.part_number=NEW.record_sub_id AND p.state<>'deleted' AND BINARY p.storage_backend=BINARY NEW.source_backend AND BINARY p.storage_key=BINARY NEW.storage_key AND BINARY p.storage_format=BINARY NEW.storage_format AND BINARY SHA2(p.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND ((NEW.object_disposition=(CASE WHEN p.state='delete_pending' THEN 'tombstone' WHEN p.sha256 IS NULL AND p.size_bytes IS NULL AND p.uploaded_at_ms IS NULL THEN 'absent' ELSE 'data' END) AND NEW.expected_sha256<=>p.sha256 AND NEW.expected_size_bytes<=>p.size_bytes AND NEW.expected_content_type<=>p.content_type) OR (p.state='staging' AND p.sha256 IS NULL AND p.size_bytes IS NULL AND p.content_type IS NULL AND p.record_count IS NULL AND p.uploaded_at_ms IS NULL AND p.delete_after_ms IS NULL AND p.deleted_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.artifact_id=p.artifact_id AND o.part_number=p.part_number AND o.completed_at_ms IS NULL) AND NEW.object_disposition='data' AND NEW.expected_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.expected_size_bytes IS NOT NULL)))) OR (NEW.record_kind='export_snapshot_pin' AND EXISTS (SELECT 1 FROM user_export_snapshot_blobs s WHERE BINARY s.request_id=BINARY NEW.record_id AND s.build_generation=NEW.record_sub_id AND s.ordinal=NEW.record_aux_id AND s.released_at_ms IS NULL AND BINARY s.storage_backend=BINARY NEW.source_backend AND s.storage_namespace_sha256 IS NULL AND BINARY s.storage_key=BINARY NEW.storage_key AND BINARY s.storage_format=BINARY NEW.storage_format AND BINARY SHA2(s.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='data' AND BINARY NEW.expected_sha256=BINARY s.source_sha256 AND NEW.expected_size_bytes=s.source_size_bytes AND NEW.expected_content_type<=>s.source_content_type)) OR (NEW.record_kind='export_delete_intent' AND EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE BINARY o.artifact_id=BINARY NEW.record_id AND o.part_number=NEW.record_sub_id AND o.deletion_generation=NEW.record_aux_id AND o.completed_at_ms IS NULL AND BINARY o.storage_backend=BINARY NEW.source_backend AND BINARY o.storage_key=BINARY NEW.storage_key AND BINARY o.storage_format=BINARY NEW.storage_format AND BINARY SHA2(o.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='tombstone' AND NEW.expected_sha256<=>o.expected_sha256 AND NEW.expected_size_bytes<=>o.expected_size_bytes AND ((NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY o.artifact_id AND p.part_number=o.part_number) AND NEW.expected_content_type IS NULL) OR EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY o.artifact_id AND p.part_number=o.part_number AND BINARY p.request_id=BINARY o.request_id AND p.build_generation=o.build_generation AND p.deletion_generation=o.deletion_generation AND BINARY p.storage_backend=BINARY o.storage_backend AND BINARY p.storage_format=BINARY o.storage_format AND BINARY p.storage_key=BINARY o.storage_key AND BINARY p.upload_token=BINARY o.upload_token AND p.sha256<=>o.expected_sha256 AND p.size_bytes<=>o.expected_size_bytes AND NEW.expected_content_type<=>p.content_type))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration inventory row is not source-bound'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_mover_inventory_bi;
CREATE TRIGGER trg_blob_mover_inventory_bi BEFORE INSERT ON blob_storage_migration_inventory FOR EACH ROW BEGIN DECLARE v_phase VARCHAR(32) DEFAULT 'invalid'; DECLARE v_migration_id VARCHAR(64) DEFAULT NULL; DECLARE v_source_backend VARCHAR(32) DEFAULT NULL; DECLARE v_source_namespace CHAR(64) DEFAULT NULL; DECLARE v_target_backend VARCHAR(32) DEFAULT NULL; DECLARE v_target_namespace CHAR(64) DEFAULT NULL; DECLARE v_started BIGINT DEFAULT NULL; SELECT phase,migration_id,source_backend,source_namespace_sha256,target_backend,target_namespace_sha256,started_at_db_ms FROM blob_storage_migration_control WHERE singleton_id=1 FOR SHARE INTO v_phase,v_migration_id,v_source_backend,v_source_namespace,v_target_backend,v_target_namespace,v_started; IF v_phase<>'frozen' OR NOT (BINARY NEW.migration_id=BINARY v_migration_id) OR NOT (BINARY NEW.source_backend=BINARY v_source_backend) OR NOT (BINARY NEW.source_namespace_sha256=BINARY v_source_namespace) OR NOT (BINARY NEW.target_backend=BINARY v_target_backend) OR NOT (BINARY NEW.target_namespace_sha256=BINARY v_target_namespace) OR NEW.created_at_db_ms<v_started OR NOT ((NEW.record_kind='blob_object' AND NEW.record_sub_id=0 AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM blob_objects b WHERE BINARY b.blob_id=BINARY NEW.record_id AND (b.state<>'deleted' OR EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL)) AND BINARY b.storage_backend=BINARY NEW.source_backend AND BINARY b.storage_key=BINARY NEW.storage_key AND BINARY b.storage_format=BINARY NEW.storage_format AND BINARY SHA2(b.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND ((NEW.object_disposition=(CASE WHEN b.state='deleted' THEN 'tombstone' WHEN b.sha256 IS NULL AND b.size_bytes IS NULL AND b.uploaded_at_ms IS NULL THEN 'absent' ELSE 'data' END) AND NEW.expected_sha256<=>(CASE WHEN b.sha256 IS NULL THEN NULL ELSE LOWER(HEX(b.sha256)) END) AND NEW.expected_size_bytes<=>b.size_bytes AND NEW.expected_content_type<=>b.content_type) OR (b.state='staging' AND b.sha256 IS NULL AND b.size_bytes IS NULL AND b.content_type IS NULL AND b.uploaded_at_ms IS NULL AND b.ready_at_ms IS NULL AND b.delete_after_ms IS NULL AND b.deleted_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL) AND NEW.object_disposition='data' AND NEW.expected_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.expected_size_bytes IS NOT NULL)))) OR (NEW.record_kind='blob_delete_intent' AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM blob_delete_outbox o JOIN blob_objects b ON b.blob_id=o.blob_id WHERE BINARY o.blob_id=BINARY NEW.record_id AND o.generation=NEW.record_sub_id AND o.completed_at_ms IS NULL AND BINARY b.storage_backend=BINARY NEW.source_backend AND BINARY b.storage_key=BINARY NEW.storage_key AND BINARY b.storage_format=BINARY NEW.storage_format AND BINARY SHA2(b.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='tombstone' AND NEW.expected_sha256<=>(CASE WHEN b.sha256 IS NULL THEN NULL ELSE LOWER(HEX(b.sha256)) END) AND NEW.expected_size_bytes<=>b.size_bytes AND NEW.expected_content_type<=>b.content_type)) OR (NEW.record_kind='export_artifact' AND NEW.record_sub_id=0 AND NEW.record_aux_id=0 AND NEW.object_disposition='metadata' AND EXISTS (SELECT 1 FROM user_export_artifacts a WHERE BINARY a.artifact_id=BINARY NEW.record_id AND a.state<>'deleted' AND BINARY a.storage_backend=BINARY NEW.source_backend)) OR (NEW.record_kind='export_part' AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY NEW.record_id AND p.part_number=NEW.record_sub_id AND p.state<>'deleted' AND BINARY p.storage_backend=BINARY NEW.source_backend AND BINARY p.storage_key=BINARY NEW.storage_key AND BINARY p.storage_format=BINARY NEW.storage_format AND BINARY SHA2(p.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND ((NEW.object_disposition=(CASE WHEN p.state='delete_pending' THEN 'tombstone' WHEN p.sha256 IS NULL AND p.size_bytes IS NULL AND p.uploaded_at_ms IS NULL THEN 'absent' ELSE 'data' END) AND NEW.expected_sha256<=>p.sha256 AND NEW.expected_size_bytes<=>p.size_bytes AND NEW.expected_content_type<=>p.content_type) OR (p.state='staging' AND p.sha256 IS NULL AND p.size_bytes IS NULL AND p.content_type IS NULL AND p.record_count IS NULL AND p.uploaded_at_ms IS NULL AND p.delete_after_ms IS NULL AND p.deleted_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.artifact_id=p.artifact_id AND o.part_number=p.part_number AND o.completed_at_ms IS NULL) AND NEW.object_disposition='data' AND NEW.expected_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.expected_size_bytes IS NOT NULL)))) OR (NEW.record_kind='export_snapshot_pin' AND EXISTS (SELECT 1 FROM user_export_snapshot_blobs s WHERE BINARY s.request_id=BINARY NEW.record_id AND s.build_generation=NEW.record_sub_id AND s.ordinal=NEW.record_aux_id AND s.released_at_ms IS NULL AND BINARY s.storage_backend=BINARY NEW.source_backend AND s.storage_namespace_sha256 IS NULL AND BINARY s.storage_key=BINARY NEW.storage_key AND BINARY s.storage_format=BINARY NEW.storage_format AND BINARY SHA2(s.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='data' AND BINARY NEW.expected_sha256=BINARY s.source_sha256 AND NEW.expected_size_bytes=s.source_size_bytes AND NEW.expected_content_type<=>s.source_content_type)) OR (NEW.record_kind='export_delete_intent' AND EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE BINARY o.artifact_id=BINARY NEW.record_id AND o.part_number=NEW.record_sub_id AND o.deletion_generation=NEW.record_aux_id AND o.completed_at_ms IS NULL AND BINARY o.storage_backend=BINARY NEW.source_backend AND BINARY o.storage_key=BINARY NEW.storage_key AND BINARY o.storage_format=BINARY NEW.storage_format AND BINARY SHA2(o.upload_token,256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='tombstone' AND NEW.expected_sha256<=>o.expected_sha256 AND NEW.expected_size_bytes<=>o.expected_size_bytes AND ((NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY o.artifact_id AND p.part_number=o.part_number) AND NEW.expected_content_type IS NULL) OR EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY o.artifact_id AND p.part_number=o.part_number AND BINARY p.request_id=BINARY o.request_id AND p.build_generation=o.build_generation AND p.deletion_generation=o.deletion_generation AND BINARY p.storage_backend=BINARY o.storage_backend AND BINARY p.storage_format=BINARY o.storage_format AND BINARY p.storage_key=BINARY o.storage_key AND BINARY p.upload_token=BINARY o.upload_token AND p.sha256<=>o.expected_sha256 AND p.size_bytes<=>o.expected_size_bytes AND NEW.expected_content_type<=>p.content_type))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration inventory row is not source-bound'; END IF; END;

DROP TRIGGER IF EXISTS trg_blob_mover_object_acks_bi_guard_a;
CREATE TRIGGER trg_blob_mover_object_acks_bi_guard_a BEFORE INSERT ON blob_storage_migration_object_acks FOR EACH ROW BEGIN DECLARE v_phase VARCHAR(32) DEFAULT 'invalid'; DECLARE v_migration_id VARCHAR(64) DEFAULT NULL; DECLARE v_target_backend VARCHAR(32) DEFAULT NULL; DECLARE v_target_namespace CHAR(64) DEFAULT NULL; SELECT phase,migration_id,target_backend,target_namespace_sha256 FROM blob_storage_migration_control WHERE singleton_id=1 FOR SHARE INTO v_phase,v_migration_id,v_target_backend,v_target_namespace; IF v_phase<>'copying' OR NOT (BINARY NEW.migration_id=BINARY v_migration_id) OR NOT (BINARY NEW.target_backend=BINARY v_target_backend) OR NOT (BINARY NEW.target_namespace_sha256=BINARY v_target_namespace) OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND BINARY i.object_disposition=BINARY NEW.object_disposition AND i.expected_sha256<=>NEW.expected_sha256 AND i.expected_size_bytes<=>NEW.expected_size_bytes AND i.expected_content_type<=>NEW.expected_content_type) OR EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND (NOT (BINARY i.object_disposition=BINARY NEW.object_disposition) OR NOT (i.expected_sha256<=>NEW.expected_sha256) OR NOT (i.expected_size_bytes<=>NEW.expected_size_bytes) OR NOT (i.expected_content_type<=>NEW.expected_content_type))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration object ack is not inventory-bound'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_mover_object_acks_bi;
CREATE TRIGGER trg_blob_mover_object_acks_bi BEFORE INSERT ON blob_storage_migration_object_acks FOR EACH ROW BEGIN DECLARE v_phase VARCHAR(32) DEFAULT 'invalid'; DECLARE v_migration_id VARCHAR(64) DEFAULT NULL; DECLARE v_target_backend VARCHAR(32) DEFAULT NULL; DECLARE v_target_namespace CHAR(64) DEFAULT NULL; SELECT phase,migration_id,target_backend,target_namespace_sha256 FROM blob_storage_migration_control WHERE singleton_id=1 FOR SHARE INTO v_phase,v_migration_id,v_target_backend,v_target_namespace; IF v_phase<>'copying' OR NOT (BINARY NEW.migration_id=BINARY v_migration_id) OR NOT (BINARY NEW.target_backend=BINARY v_target_backend) OR NOT (BINARY NEW.target_namespace_sha256=BINARY v_target_namespace) OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND BINARY i.object_disposition=BINARY NEW.object_disposition AND i.expected_sha256<=>NEW.expected_sha256 AND i.expected_size_bytes<=>NEW.expected_size_bytes AND i.expected_content_type<=>NEW.expected_content_type) OR EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND (NOT (BINARY i.object_disposition=BINARY NEW.object_disposition) OR NOT (i.expected_sha256<=>NEW.expected_sha256) OR NOT (i.expected_size_bytes<=>NEW.expected_size_bytes) OR NOT (i.expected_content_type<=>NEW.expected_content_type))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration object ack is not inventory-bound'; END IF; END;

