CREATE TRIGGER trg_blob_mover_events_bi_guard_a BEFORE INSERT ON blob_storage_migration_events FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND c.phase<>'inactive' AND c.inventory_entry_count=NEW.inventory_entry_count AND c.inventory_root_sha256<=>NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND c.object_ack_root_sha256<=>NEW.object_ack_root_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration event is not control-bound'; END IF; END;
