CREATE TRIGGER trg_blob_mover_events_bi BEFORE INSERT ON blob_storage_migration_events FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND c.phase<>'inactive' AND c.inventory_entry_count=NEW.inventory_entry_count AND c.inventory_root_sha256<=>NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND c.object_ack_root_sha256<=>NEW.object_ack_root_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration event is not control-bound'; END IF; END;

DROP TRIGGER IF EXISTS trg_blob_mover_receipts_bi_guard_a;
CREATE TRIGGER trg_blob_mover_receipts_bi_guard_a BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.blob_control_evidence_sha256 IS NULL AND CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)>=c.source_cleanup_not_before_db_ms))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_mover_receipts_bi;
CREATE TRIGGER trg_blob_mover_receipts_bi BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.blob_control_evidence_sha256 IS NULL AND CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)>=c.source_cleanup_not_before_db_ms))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;

