CREATE TRIGGER trg_blob_mover_source_cleanup_bi_guard_a BEFORE INSERT ON blob_storage_migration_source_cleanup_acks FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase='committed' AND BINARY c.migration_id=BINARY NEW.migration_id AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)>=c.source_cleanup_not_before_db_ms) OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE a.migration_id=NEW.migration_id AND BINARY a.storage_key=BINARY NEW.storage_key AND BINARY a.object_disposition=BINARY NEW.object_disposition AND a.source_descriptor_sha256<=>NEW.source_descriptor_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration source cleanup ack is not authorized'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_mover_source_cleanup_bi;
CREATE TRIGGER trg_blob_mover_source_cleanup_bi BEFORE INSERT ON blob_storage_migration_source_cleanup_acks FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase='committed' AND BINARY c.migration_id=BINARY NEW.migration_id AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)>=c.source_cleanup_not_before_db_ms) OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE a.migration_id=NEW.migration_id AND BINARY a.storage_key=BINARY NEW.storage_key AND BINARY a.object_disposition=BINARY NEW.object_disposition AND a.source_descriptor_sha256<=>NEW.source_descriptor_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration source cleanup ack is not authorized'; END IF; END;

