-- Durable DB freeze. These guards do not rely on a forgeable session variable. During an active
-- attempt every ordinary mutation is rejected. The sole update exception is a source->target
-- pointer rewrite in phase `cutting_over`, bound to an immutable inventory row and verified ACK.
-- The coordinator still locks the singleton first and performs all rewrites plus generation-1
-- activation and the committed receipt in one InnoDB transaction.
DROP TRIGGER IF EXISTS trg_blob_mover_objects_bi_freeze_guard_a;
CREATE TRIGGER trg_blob_mover_objects_bi_freeze_guard_a BEFORE INSERT ON blob_objects FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase IN ('frozen','inventory_sealed','copying','verified','cutting_over','committed','abort_cleaning')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration freeze rejects blob insert'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_mover_objects_bi_freeze;
CREATE TRIGGER trg_blob_mover_objects_bi_freeze BEFORE INSERT ON blob_objects FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase IN ('frozen','inventory_sealed','copying','verified','cutting_over','committed','abort_cleaning')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration freeze rejects blob insert'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_mover_objects_bd_freeze_guard_a;
CREATE TRIGGER trg_blob_mover_objects_bd_freeze_guard_a BEFORE DELETE ON blob_objects FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase IN ('frozen','inventory_sealed','copying','verified','cutting_over','committed','abort_cleaning')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration freeze rejects blob delete'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_mover_objects_bd_freeze;
CREATE TRIGGER trg_blob_mover_objects_bd_freeze BEFORE DELETE ON blob_objects FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase IN ('frozen','inventory_sealed','copying','verified','cutting_over','committed','abort_cleaning')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration freeze rejects blob delete'; END IF; END;

DROP TRIGGER IF EXISTS trg_blob_storage_object_bu_bootstrap;
DROP TRIGGER IF EXISTS trg_blob_storage_object_bu_guard_a;
DROP TRIGGER IF EXISTS trg_blob_storage_object_bu;
CREATE TRIGGER trg_blob_storage_object_bu_guard_a BEFORE UPDATE ON blob_objects FOR EACH ROW BEGIN DECLARE v_generation BIGINT UNSIGNED DEFAULT 1; DECLARE v_backend VARCHAR(32) DEFAULT NULL; DECLARE v_phase VARCHAR(32) DEFAULT 'invalid'; DECLARE v_migration_id VARCHAR(64) DEFAULT NULL; DECLARE v_source_backend VARCHAR(32) DEFAULT NULL; DECLARE v_target_backend VARCHAR(32) DEFAULT NULL; SELECT control_generation,storage_backend FROM blob_storage_control WHERE singleton_id=1 FOR SHARE INTO v_generation,v_backend; SELECT phase,migration_id,source_backend,target_backend FROM blob_storage_migration_control WHERE singleton_id=1 FOR SHARE INTO v_phase,v_migration_id,v_source_backend,v_target_backend; IF v_phase IN ('frozen','inventory_sealed','copying','verified','cutting_over','committed','abort_cleaning') THEN IF NOT (v_phase='cutting_over' AND BINARY OLD.storage_backend=BINARY v_source_backend AND BINARY NEW.storage_backend=BINARY v_target_backend AND JSON_ARRAY(OLD.blob_id,OLD.tenant_id,OLD.user_id,OLD.session_id,OLD.item_id,OLD.purpose,OLD.storage_format,OLD.storage_key,OLD.upload_token,OLD.state,HEX(OLD.sha256),OLD.size_bytes,OLD.content_type,OLD.uploaded_at_ms,OLD.ready_at_ms,OLD.staging_expires_at_ms,OLD.delete_after_ms,OLD.deleted_at_ms,OLD.deletion_generation,OLD.created_at_ms)=JSON_ARRAY(NEW.blob_id,NEW.tenant_id,NEW.user_id,NEW.session_id,NEW.item_id,NEW.purpose,NEW.storage_format,NEW.storage_key,NEW.upload_token,NEW.state,HEX(NEW.sha256),NEW.size_bytes,NEW.content_type,NEW.uploaded_at_ms,NEW.ready_at_ms,NEW.staging_expires_at_ms,NEW.delete_after_ms,NEW.deleted_at_ms,NEW.deletion_generation,NEW.created_at_ms) AND EXISTS (SELECT 1 FROM blob_storage_migration_inventory i JOIN blob_storage_migration_object_acks a ON a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition AND a.expected_sha256<=>i.expected_sha256 AND a.expected_size_bytes<=>i.expected_size_bytes AND a.expected_content_type<=>i.expected_content_type WHERE BINARY i.migration_id=BINARY v_migration_id AND i.record_kind='blob_object' AND BINARY i.record_id=BINARY OLD.blob_id AND i.record_sub_id=OLD.deletion_generation AND i.record_aux_id=0 AND BINARY i.source_backend=BINARY OLD.storage_backend AND BINARY i.target_backend=BINARY NEW.storage_backend AND BINARY i.storage_key=BINARY OLD.storage_key)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration freeze rejects blob update'; END IF; ELSEIF NOT (BINARY OLD.storage_backend=BINARY NEW.storage_backend) OR (v_generation<>0 AND (v_backend IS NULL OR NOT (BINARY NEW.storage_backend=BINARY v_backend))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob storage backend is immutable or inactive'; END IF; END;
