ge_migration_inventory i JOIN blob_storage_migration_object_acks a ON a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition AND a.expected_sha256<=>i.expected_sha256 AND a.expected_size_bytes<=>i.expected_size_bytes AND a.expected_content_type<=>i.expected_content_type WHERE BINARY i.migration_id=BINARY v_migration_id AND i.record_kind='export_snapshot_pin' AND BINARY i.record_id=BINARY OLD.request_id AND i.record_sub_id=OLD.build_generation AND i.record_aux_id=OLD.ordinal AND BINARY i.source_backend=BINARY OLD.storage_backend AND BINARY i.target_backend=BINARY NEW.storage_backend AND BINARY i.target_namespace_sha256=BINARY NEW.storage_namespace_sha256 AND BINARY i.storage_key=BINARY OLD.storage_key)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration freeze rejects snapshot update'; END IF; ELSEIF NOT (BINARY OLD.storage_backend=BINARY NEW.storage_backend) OR NOT (OLD.storage_namespace_sha256<=>NEW.storage_namespace_sha256) OR (v_generation<>0 AND NEW.released_at_ms IS NULL AND (v_backend IS NULL OR v_namespace IS NULL OR NOT (BINARY NEW.storage_backend=BINARY v_backend) OR NEW.storage_namespace_sha256 IS NULL OR NOT (BINARY NEW.storage_namespace_sha256=BINARY v_namespace))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='snapshot storage namespace is immutable or inactive'; END IF; END;
