xpected_size_bytes<=>i.expected_size_bytes AND a.expected_content_type<=>i.expected_content_type WHERE BINARY i.migration_id=BINARY v_migration_id AND i.record_kind='export_delete_intent' AND BINARY i.record_id=BINARY CAST(OLD.outbox_id AS CHAR) AND i.record_sub_id=OLD.deletion_generation AND i.record_aux_id=OLD.part_number AND BINARY i.source_backend=BINARY OLD.storage_backend AND BINARY i.target_backend=BINARY NEW.storage_backend AND BINARY i.storage_key=BINARY OLD.storage_key)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration freeze rejects export delete intent update'; END IF; ELSEIF NOT (BINARY OLD.storage_backend=BINARY NEW.storage_backend) OR (v_generation<>0 AND (v_backend IS NULL OR NOT (BINARY NEW.storage_backend=BINARY v_backend))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='export delete intent backend is immutable or inactive'; END IF; END;
