-- Replace the preliminary control guards now that every referenced ledger and freeze guard exists.
-- The evidence digest is SQL-derived from the complete projection; callers cannot carry an old
-- digest across a phase, root, delay, namespace, or receipt change.
DROP TRIGGER IF EXISTS trg_blob_mover_control_bu_guard_a;
DROP TRIGGER IF EXISTS trg_blob_mover_control_bu;
DROP TRIGGER IF EXISTS trg_blob_mover_control_bu_invariants;
CREATE TRIGGER trg_blob_mover_control_bu_invariants BEFORE UPDATE ON blob_storage_migration_control FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); DECLARE v_expected_evidence CHAR(64); SET v_expected_evidence=SHA2(CONCAT_WS(CHAR(10),'blob-storage-migration-control-v1',CAST(NEW.control_generation AS CHAR),COALESCE(NEW.migration_id,'-'),NEW.phase,COALESCE(NEW.source_backend,'-'),COALESCE(NEW.source_namespace_sha256,'-'),COALESCE(NEW.target_backend,'-'),COALESCE(NEW.target_namespace_sha256,'-'),COALESCE(CAST(NEW.rollback_window_ms AS CHAR),'-'),COALESCE(CAST(NEW.source_cleanup_delay_ms AS CHAR),'-'),COALESCE(CAST(NEW.cutover_not_before_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.source_cleanup_not_before_db_ms AS CHAR),'-'),CAST(NEW.inventory_entry_count AS CHAR),COALESCE(NEW.inventory_root_sha256,'-'),CAST(NEW.object_ack_count AS CHAR),COALESCE(NEW.object_ack_root_sha256,'-'),COALESCE(CAST(NEW.started_at_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.inventory_sealed_at_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.verified_at_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.completed_at_db_ms AS CHAR),'-'),COALESCE(NEW.terminal_receipt_sha256,'-'),COALESCE(NEW.fleet_drained_evidence_sha256,'-')),256); IF NOT (BINARY NEW.evidence_sha256=BINARY v_expected_evidence) OR NOT (((OLD.phase='inactive' OR OLD.phase='aborted') AND NEW.phase='frozen' AND NEW.control_generation=OLD.control_generation+1 AND NEW.started_at_db_ms=v_now AND NEW.cutover_not_before_db_ms=NEW.started_at_db_ms+NEW.rollback_window_ms AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.inventory_entry_count=0 AND NEW.inventory_root_sha256 IS NULL AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.inventory_sealed_at_db_ms IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND NOT (NEW.target_namespace_sha256<=>OLD.target_namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE BINARY i.migration_id=BINARY NEW.migration_id OR BINARY i.target_namespace_sha256=BINARY NEW.target_namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_events e WHERE BINARY e.migration_id=BINARY NEW.migration_id) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE BINARY r.migration_id=BINARY NEW.migration_id OR BINARY r.target_namespace_sha256=BINARY NEW.target_namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE BINARY a.migration_id=BINARY NEW.migration_id) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_source_cleanup_acks a WHERE BINARY a.migration_id=BINARY NEW.migration_id) AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0) AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.completed_at_ms IS NULL AND o.claim_token IS NOT NULL AND o.lease_until_ms>=v_now) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.completed_at_ms IS NULL AND o.claim_token IS NOT NULL AND o.lease_until_ms>=v_now) AND NOT EXISTS (SELECT 1 FROM user_export_download_leases l WHERE l.lease_until_ms>=v_now)) OR (OLD.phase NOT IN ('inactive','aborted') AND NEW.control_generation=OLD.control_generation AND BINARY NEW.migration_id=BINARY OLD.migration_id AND BINARY NEW.source_backend=BINARY OLD.source_backend AND BINARY NEW.source_namespace_sha256=BINARY OLD.source_namespace_sha256 AND BINARY NEW.target_backend=BINARY OLD.target_backend AND BINARY NEW.target_namespace_sha256=BINARY OLD.target_namespace_sha256 AND NEW.rollback_window_ms=OLD.rollback_window_ms AND NEW.source_cleanup_delay_ms=OLD.source_cleanup_delay_ms AND NEW.cutover_not_before_db_ms=OLD.cutover_not_before_db_ms AND NEW.started_at_db_ms=OLD.started_at_db_ms AND BINARY NEW.fleet_drained_evidence_sha256=BINARY OLD.fleet_drained_evidence_sha256 AND ((OLD.phase='cutting_over' AND NEW.phase='committed' AND NEW.completed_at_db_ms=v_now AND NEW.source_cleanup_not_before_db_ms=NEW.completed_at_db_ms+NEW.source_cleanup_delay_ms) OR (NOT (OLD.phase='cutting_over' AND NEW.phase='committed') AND NEW.source_cleanup_not_before_db_ms<=>OLD.source_cleanup_not_before_db_ms)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control invariant is not permitted'; END IF; END;

CREATE TRIGGER trg_blob_mover_control_bu BEFORE UPDATE ON blob_storage_migration_control FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NOT (OLD.singleton_id=1 AND NEW.singleton_id=1 AND (((OLD.phase IN ('inactive','aborted')) AND NEW.phase='frozen') OR (OLD.phase='frozen' AND NEW.phase='inventory_sealed' AND NEW.inventory_entry_count=(SELECT COUNT(*) FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id) AND NEW.inventory_root_sha256 IS NOT NULL AND NEW.inventory_sealed_at_db_ms=v_now AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND NOT EXISTS (SELECT 1 FROM blob_objects b WHERE (b.state<>'deleted' OR EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL)) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='blob_object' AND BINARY i.record_id=BINARY b.blob_id AND i.record_sub_id=0 AND i.record_aux_id=0)) AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.completed_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='blob_delete_intent' AND BINARY i.record_id=BINARY o.blob_id AND i.record_sub_id=o.generation AND i.record_aux_id=0)) AND NOT EXISTS (SELECT 1 FROM user_export_artifacts a WHERE a.state<>'deleted' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_artifact' AND BINARY i.record_id=BINARY a.artifact_id AND i.record_sub_id=0 AND i.record_aux_id=0)) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE p.state<>'deleted' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_part' AND BINARY i.record_id=BINARY p.artifact_id AND i.record_sub_id=p.part_number AND i.record_aux_id=0)) AND NOT EXISTS (SELECT 1 FROM user_export_snapshot_blobs s WHERE s.released_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_snapshot_pin' AND BINARY i.record_id=BINARY s.request_id AND i.record_sub_id=s.build_generation AND i.record_aux_id=s.ordinal)) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.completed_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_delete_intent' AND BINARY i.record_id=BINARY o.artifact_id AND i.record_sub_id=o.part_number AND i.record_aux_id=o.deletion_generation)) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i JOIN blob_storage_migration_inventory j ON j.migration_id=i.migration_id AND BINARY j.storage_key=BINARY i.storage_key AND j.entry_ordinal<>i.entry_ordinal WHERE i.migration_id=OLD.migration_id AND i.storage_key IS NOT NULL AND (NOT (BINARY i.object_disposition=BINARY j.object_disposition) OR NOT (i.expected_sha256<=>j.expected_sha256) OR NOT (i.expected_size_bytes<=>j.expected_size_bytes) OR NOT (i.expected_content_type<=>j.expected_content_type)))) OR (OLD.phase='inventory_sealed' AND NEW.phase='copying' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase='copying' AND NEW.phase='verified' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_object_acks a WHERE a.migration_id=OLD.migration_id) AND NEW.object_ack_root_sha256 IS NOT NULL AND NEW.verified_at_db_ms=v_now AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition AND a.expected_sha256<=>i.expected_sha256 AND a.expected_size_bytes<=>i.expected_size_bytes AND a.expected_content_type<=>i.expected_content_type))) OR (OLD.phase IN ('frozen','inventory_sealed','copying','verified') AND NEW.phase='abort_cleaning' AND NEW.inventory_entry_count=(SELECT COUNT(*) FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id) AND NEW.inventory_root_sha256 IS NOT NULL AND NEW.inventory_sealed_at_db_ms=(CASE WHEN OLD.inventory_sealed_at_db_ms IS NULL THEN v_now ELSE OLD.inventory_sealed_at_db_ms END) AND NEW.object_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_object_acks a WHERE a.migration_id=OLD.migration_id) AND NEW.object_ack_root_sha256 IS NOT NULL AND NEW.verified_at_db_ms<=>OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (OLD.phase='verified' AND NEW.phase='cutting_over' AND v_now>=OLD.cutover_not_before_db_ms AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL) OR (OLD.phase='cutting_over' AND NEW.phase='committed' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms=v_now AND NEW.terminal_receipt_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r JOIN blob_storage_control b ON b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY OLD.target_backend AND BINARY b.namespace_sha256=BINARY OLD.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY r.blob_control_evidence_sha256 WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='committed' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256)) OR (OLD.phase='abort_cleaning' AND NEW.phase='aborted' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms<=>OLD.verified_at_db_ms AND NEW.completed_at_db_ms=v_now AND NEW.terminal_receipt_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='aborted' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256)) OR (OLD.phase='committed' AND NEW.phase='source_cleaned' AND v_now>=OLD.source_cleanup_not_before_db_ms AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND NEW.completed_at_db_ms=OLD.completed_at_db_ms AND BINARY NEW.terminal_receipt_sha256=BINARY OLD.terminal_receipt_sha256 AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='source_cleaned') AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control transition is not permitted'; END IF; END;

-- Receipt metadata must repeat every durable timing/namespace/operator commitment exactly.
DROP TRIGGER IF EXISTS trg_blob_mover_receipts_commitments_bi;
CREATE TRIGGER trg_blob_mover_receipts_commitments_bi BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.rollback_window_ms=NEW.rollback_window_ms AND c.source_cleanup_delay_ms=NEW.source_cleanup_delay_ms AND c.cutover_not_before_db_ms=NEW.cutover_not_before_db_ms AND c.source_cleanup_not_before_db_ms<=>NEW.source_cleanup_not_before_db_ms AND BINARY c.fleet_drained_evidence_sha256=BINARY NEW.fleet_drained_evidence_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt commitments do not match control'; END IF; END;

-- Final evidence guards. These definitions intentionally replace the bootstrap variants above
-- only after every referenced table and runtime freeze guard exists, so DDL interruption remains
-- replayable while the migration marker is absent.
DROP TRIGGER IF EXISTS trg_blob_mover_inventory_bi_guard_a;
DROP TRIGGER IF EXISTS trg_blob_mover_inventory_bi;
CREATE TRIGGER trg_blob_mover_inventory_bi_guard_a BEFORE INSERT ON blob_storage_migration_inventory FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase='frozen' AND BINARY c.migration_id=BINARY NEW.migration_id AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND NEW.created_at_db_ms>=c.started_at_db_ms AND NEW.created_at_db_ms<=v_now) OR NEW.entry_ordinal<>(SELECT COALESCE(MAX(i.entry_ordinal),0)+1 FROM blob_storage_migration_inventory i WHERE BINARY i.migration_id=BINARY NEW.migration_id) OR NOT ((NEW.record_kind='blob_object' AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM blob_objects b WHERE BINARY b.blob_id=BINARY NEW.record_id AND b.deletion_generation=NEW.record_sub_id AND (b.state<>'deleted' OR EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL)) AND BINARY b.storage_backend=BINARY NEW.source_backend AND BINARY b.storage_key=BINARY NEW.storage_key AND BINARY b.storage_format=BINARY NEW.storage_format AND BINARY SHA2(CONCAT('["blob-storage-migration-upload-token-v1","',b.upload_token,'"]'),256)=BINARY NEW.source_upload_token_sha256 AND ((NEW.object_disposition=(CASE WHEN b.state IN ('delete_pending','deleted') OR EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL) THEN 'tombstone' WHEN b.state='ready' OR (b.sha256 IS NOT NULL AND b.size_bytes IS NOT NULL) THEN 'data' ELSE 'absent' END) AND NEW.expected_sha256<=>(CASE WHEN b.sha256 IS NULL THEN NULL ELSE LOWER(HEX(b.sha256)) END) AND NEW.expected_size_bytes<=>b.size_bytes AND NEW.expected_content_type<=>b.content_type) OR (b.state='staging' AND b.sha256 IS NULL AND b.size_bytes IS NULL AND b.content_type IS NULL AND b.uploaded_at_ms IS NULL AND b.ready_at_ms IS NULL AND b.delete_after_ms IS NULL AND b.deleted_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL) AND NEW.object_disposition='data' AND NEW.expected_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.expected_size_bytes IS NOT NULL)))) OR (NEW.record_kind='blob_delete_intent' AND NEW.record_aux_id=0 AND EXISTS (SELECT 1 FROM blob_delete_outbox o JOIN blob_objects b ON b.blob_id=o.blob_id WHERE BINARY CAST(o.outbox_id AS CHAR)=BINARY NEW.record_id AND o.generation=NEW.record_sub_id AND o.completed_at_ms IS NULL AND BINARY b.storage_backend=BINARY NEW.source_backend AND BINARY b.storage_key=BINARY NEW.storage_key AND BINARY b.storage_format=BINARY NEW.storage_format AND BINARY SHA2(CONCAT('["blob-storage-migration-upload-token-v1","',b.upload_token,'"]'),256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='tombstone' AND NEW.expected_sha256<=>(CASE WHEN b.sha256 IS NULL THEN NULL ELSE LOWER(HEX(b.sha256)) END) AND NEW.expected_size_bytes<=>b.size_bytes AND NEW.expected_content_type<=>b.content_type)) OR (NEW.record_kind='export_artifact' AND NEW.record_aux_id=0 AND NEW.object_disposition='metadata' AND EXISTS (SELECT 1 FROM user_export_artifacts a WHERE BINARY a.artifact_id=BINARY NEW.record_id AND a.build_generation=NEW.record_sub_id AND a.state<>'deleted' AND BINARY a.storage_backend=BINARY NEW.source_backend)) OR (NEW.record_kind='export_part' AND EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY NEW.record_id AND p.part_number=NEW.record_sub_id AND p.build_generation=NEW.record_aux_id AND (p.state<>'deleted' OR EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.artifact_id=p.artifact_id AND o.part_number=p.part_number AND o.completed_at_ms IS NULL)) AND BINARY p.storage_backend=BINARY NEW.source_backend AND BINARY p.storage_key=BINARY NEW.storage_key AND BINARY p.storage_format=BINARY NEW.storage_format AND BINARY SHA2(CONCAT('["blob-storage-migration-upload-token-v1","',p.upload_token,'"]'),256)=BINARY NEW.source_upload_token_sha256 AND ((NEW.object_disposition=(CASE WHEN p.state IN ('delete_pending','deleted') OR EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.artifact_id=p.artifact_id AND o.part_number=p.part_number AND o.completed_at_ms IS NULL) THEN 'tombstone' WHEN p.state='uploaded' OR (p.sha256 IS NOT NULL AND p.size_bytes IS NOT NULL) THEN 'data' ELSE 'absent' END) AND NEW.expected_sha256<=>p.sha256 AND NEW.expected_size_bytes<=>p.size_bytes AND NEW.expected_content_type<=>p.content_type) OR (p.state='staging' AND p.sha256 IS NULL AND p.size_bytes IS NULL AND p.content_type IS NULL AND p.record_count IS NULL AND p.uploaded_at_ms IS NULL AND p.delete_after_ms IS NULL AND p.deleted_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.artifact_id=p.artifact_id AND o.part_number=p.part_number AND o.completed_at_ms IS NULL) AND NEW.object_disposition='data' AND NEW.expected_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.expected_size_bytes IS NOT NULL)))) OR (NEW.record_kind='export_snapshot_pin' AND EXISTS (SELECT 1 FROM user_export_snapshot_blobs s WHERE BINARY s.request_id=BINARY NEW.record_id AND s.build_generation=NEW.record_sub_id AND s.ordinal=NEW.record_aux_id AND s.released_at_ms IS NULL AND BINARY s.storage_backend=BINARY NEW.source_backend AND s.storage_namespace_sha256 IS NULL AND BINARY s.storage_key=BINARY NEW.storage_key AND BINARY s.storage_format=BINARY NEW.storage_format AND BINARY SHA2(CONCAT('["blob-storage-migration-upload-token-v1","',s.upload_token,'"]'),256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='data' AND BINARY NEW.expected_sha256=BINARY s.source_sha256 AND NEW.expected_size_bytes=s.source_size_bytes AND NEW.expected_content_type<=>s.source_content_type)) OR (NEW.record_kind='export_delete_intent' AND EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE BINARY CAST(o.outbox_id AS CHAR)=BINARY NEW.record_id AND o.deletion_generation=NEW.record_sub_id AND o.part_number=NEW.record_aux_id AND o.completed_at_ms IS NULL AND BINARY o.storage_backend=BINARY NEW.source_backend AND BINARY o.storage_key=BINARY NEW.storage_key AND BINARY o.storage_format=BINARY NEW.storage_format AND BINARY SHA2(CONCAT('["blob-storage-migration-upload-token-v1","',o.upload_token,'"]'),256)=BINARY NEW.source_upload_token_sha256 AND NEW.object_disposition='tombstone' AND NEW.expected_sha256<=>o.expected_sha256 AND NEW.expected_size_bytes<=>o.expected_size_bytes AND ((NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY o.artifact_id AND p.part_number=o.part_number) AND NEW.expected_content_type IS NULL) OR EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE BINARY p.artifact_id=BINARY o.artifact_id AND p.part_number=o.part_number AND BINARY p.request_id=BINARY o.request_id AND p.build_generation=o.build_generation AND p.deletion_generation=o.deletion_generation AND BINARY p.storage_backend=BINARY o.storage_backend AND BINARY p.storage_format=BINARY o.storage_format AND BINARY p.storage_key=BINARY o.storage_key AND BINARY p.upload_token=BINARY o.upload_token AND p.sha256<=>o.expected_sha256 AND p.size_bytes<=>o.expected_size_bytes AND NEW.expected_content_type<=>p.content_type))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration inventory row is not source-bound'; END IF; END;
