CREATE TRIGGER trg_blob_mover_object_acks_bi_guard_a BEFORE INSERT ON blob_storage_migration_object_acks FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.verified_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase='copying' AND BINARY c.migration_id=BINARY NEW.migration_id AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND NEW.verified_at_db_ms>=c.inventory_sealed_at_db_ms) OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND BINARY i.object_disposition=BINARY NEW.object_disposition AND i.expected_sha256<=>NEW.expected_sha256 AND i.expected_size_bytes<=>NEW.expected_size_bytes AND i.expected_content_type<=>NEW.expected_content_type AND i.object_disposition<>'metadata') OR EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND (NOT (BINARY i.object_disposition=BINARY NEW.object_disposition) OR NOT (i.expected_sha256<=>NEW.expected_sha256) OR NOT (i.expected_size_bytes<=>NEW.expected_size_bytes) OR NOT (i.expected_content_type<=>NEW.expected_content_type))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration object ack is not inventory-bound'; END IF; END;
CREATE TRIGGER trg_blob_mover_object_acks_bi BEFORE INSERT ON blob_storage_migration_object_acks FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.verified_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND c.phase='copying' AND BINARY c.migration_id=BINARY NEW.migration_id AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND NEW.verified_at_db_ms>=c.inventory_sealed_at_db_ms) OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND BINARY i.object_disposition=BINARY NEW.object_disposition AND i.expected_sha256<=>NEW.expected_sha256 AND i.expected_size_bytes<=>NEW.expected_size_bytes AND i.expected_content_type<=>NEW.expected_content_type AND i.object_disposition<>'metadata') OR EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=NEW.migration_id AND BINARY i.storage_key=BINARY NEW.storage_key AND (NOT (BINARY i.object_disposition=BINARY NEW.object_disposition) OR NOT (i.expected_sha256<=>NEW.expected_sha256) OR NOT (i.expected_size_bytes<=>NEW.expected_size_bytes) OR NOT (i.expected_content_type<=>NEW.expected_content_type))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration object ack is not inventory-bound'; END IF; END;

DROP TRIGGER IF EXISTS trg_blob_mover_receipts_commitments_bi;
