CREATE TRIGGER trg_blob_mover_receipts_bi_guard_a BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.occurred_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.rollback_window_ms=NEW.rollback_window_ms AND c.source_cleanup_delay_ms=NEW.source_cleanup_delay_ms AND c.cutover_not_before_db_ms=NEW.cutover_not_before_db_ms AND BINARY c.fleet_drained_evidence_sha256=BINARY NEW.fleet_drained_evidence_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND NEW.source_cleanup_not_before_db_ms=NEW.occurred_at_db_ms+NEW.source_cleanup_delay_ms AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_target_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.target_cleanup_ack_root_sha256 IS NOT NULL AND NEW.occurred_at_db_ms>=c.inventory_sealed_at_db_ms AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.source_cleanup_not_before_db_ms=c.source_cleanup_not_before_db_ms AND NEW.source_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.source_cleanup_ack_root_sha256 IS NOT NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.source_cleanup_not_before_db_ms AND NEW.blob_control_evidence_sha256 IS NULL))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;
CREATE TRIGGER trg_blob_mover_receipts_bi BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.occurred_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.rollback_window_ms=NEW.rollback_window_ms AND c.source_cleanup_delay_ms=NEW.source_cleanup_delay_ms AND c.cutover_not_before_db_ms=NEW.cutover_not_before_db_ms AND BINARY c.fleet_drained_evidence_sha256=BINARY NEW.fleet_drained_evidence_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND NEW.source_cleanup_not_before_db_ms=NEW.occurred_at_db_ms+NEW.source_cleanup_delay_ms AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_target_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.target_cleanup_ack_root_sha256 IS NOT NULL AND NEW.occurred_at_db_ms>=c.inventory_sealed_at_db_ms AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.source_cleanup_not_before_db_ms=c.source_cleanup_not_before_db_ms AND NEW.source_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.source_cleanup_ack_root_sha256 IS NOT NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.source_cleanup_not_before_db_ms AND NEW.blob_control_evidence_sha256 IS NULL))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;

DROP TRIGGER IF EXISTS trg_blob_mover_control_bu_guard_a;
DROP TRIGGER IF EXISTS trg_blob_mover_control_bu;
DROP TRIGGER IF EXISTS trg_blob_mover_control_bu_invariants;
DROP TRIGGER IF EXISTS trg_blob_mover_control_receipt_visibility_bu;
CREATE TRIGGER trg_blob_mover_control_receipt_visibility_bu BEFORE UPDATE ON blob_storage_migration_control FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); DECLARE v_receipt_sha256 CHAR(64) DEFAULT NULL; IF OLD.phase='committed' AND NEW.phase='source_cleaned' THEN SELECT receipt_sha256 INTO v_receipt_sha256 FROM blob_storage_migration_receipts WHERE BINARY migration_id=BINARY OLD.migration_id AND receipt_kind='source_cleaned' AND BINARY receipt_sha256=BINARY NEW.terminal_receipt_sha256 AND source_cleanup_ack_count=NEW.source_cleanup_ack_count AND BINARY source_cleanup_ack_root_sha256=BINARY NEW.source_cleanup_ack_root_sha256 FOR SHARE; IF v_receipt_sha256 IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration source cleanup receipt is not visible'; END IF; IF v_now<OLD.source_cleanup_not_before_db_ms OR NEW.inventory_entry_count<>OLD.inventory_entry_count OR NOT (BINARY NEW.inventory_root_sha256<=>BINARY OLD.inventory_root_sha256) OR NOT (NEW.inventory_sealed_at_db_ms<=>OLD.inventory_sealed_at_db_ms) OR NEW.object_ack_count<>OLD.object_ack_count OR NOT (BINARY NEW.object_ack_root_sha256<=>BINARY OLD.object_ack_root_sha256) OR NEW.source_cleanup_ack_count<>(SELECT COUNT(*) FROM blob_storage_migration_source_cleanup_acks a WHERE BINARY a.migration_id=BINARY OLD.migration_id) OR NEW.source_cleanup_ack_root_sha256 IS NULL OR NEW.target_cleanup_ack_count<>0 OR NEW.target_cleanup_ack_root_sha256 IS NOT NULL OR NOT (NEW.verified_at_db_ms<=>OLD.verified_at_db_ms) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration source cleanup transition is not permitted'; END IF; IF EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE BINARY i.migration_id=BINARY OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_source_cleanup_acks a WHERE BINARY a.migration_id=BINARY i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration source cleanup coverage is incomplete'; END IF; END IF; END;
CREATE TRIGGER trg_blob_mover_control_bu_invariants BEFORE UPDATE ON blob_storage_migration_control FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); DECLARE v_expected_evidence CHAR(64); SET v_expected_evidence=SHA2(CONCAT_WS(CHAR(10),'blob-storage-migration-control-v1',CAST(NEW.control_generation AS CHAR),COALESCE(NEW.migration_id,'-'),NEW.phase,COALESCE(NEW.source_backend,'-'),COALESCE(NEW.source_namespace_sha256,'-'),COALESCE(NEW.target_backend,'-'),COALESCE(NEW.target_namespace_sha256,'-'),COALESCE(CAST(NEW.rollback_window_ms AS CHAR),'-'),COALESCE(CAST(NEW.source_cleanup_delay_ms AS CHAR),'-'),COALESCE(CAST(NEW.cutover_not_before_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.source_cleanup_not_before_db_ms AS CHAR),'-'),CAST(NEW.inventory_entry_count AS CHAR),COALESCE(NEW.inventory_root_sha256,'-'),CAST(NEW.object_ack_count AS CHAR),COALESCE(NEW.object_ack_root_sha256,'-'),CAST(NEW.source_cleanup_ack_count AS CHAR),COALESCE(NEW.source_cleanup_ack_root_sha256,'-'),CAST(NEW.target_cleanup_ack_count AS CHAR),COALESCE(NEW.target_cleanup_ack_root_sha256,'-'),COALESCE(CAST(NEW.started_at_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.inventory_sealed_at_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.verified_at_db_ms AS CHAR),'-'),COALESCE(CAST(NEW.completed_at_db_ms AS CHAR),'-'),COALESCE(NEW.terminal_receipt_sha256,'-'),COALESCE(NEW.fleet_drained_evidence_sha256,'-')),256); IF NOT (OLD.singleton_id=1 AND NEW.singleton_id=1 AND BINARY NEW.evidence_sha256=BINARY v_expected_evidence AND (((OLD.phase IN ('inactive','aborted')) AND NEW.phase='frozen' AND NEW.control_generation=OLD.control_generation+1 AND NEW.started_at_db_ms<=v_now AND (OLD.completed_at_db_ms IS NULL OR NEW.started_at_db_ms>=OLD.completed_at_db_ms) AND NEW.cutover_not_before_db_ms=NEW.started_at_db_ms+NEW.rollback_window_ms AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.inventory_entry_count=0 AND NEW.inventory_root_sha256 IS NULL AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.inventory_sealed_at_db_ms IS NULL AND NEW.verified_at_db_ms IS NULL AND NEW.completed_at_db_ms IS NULL AND NEW.terminal_receipt_sha256 IS NULL AND NOT (NEW.target_namespace_sha256<=>OLD.target_namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE BINARY i.migration_id=BINARY NEW.migration_id OR BINARY i.target_namespace_sha256=BINARY NEW.target_namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_events e WHERE BINARY e.migration_id=BINARY NEW.migration_id) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE BINARY r.migration_id=BINARY NEW.migration_id OR BINARY r.target_namespace_sha256=BINARY NEW.target_namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE BINARY a.migration_id=BINARY NEW.migration_id OR BINARY a.target_namespace_sha256=BINARY NEW.target_namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_source_cleanup_acks a WHERE BINARY a.migration_id=BINARY NEW.migration_id) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_target_cleanup_acks a WHERE BINARY a.migration_id=BINARY NEW.migration_id OR BINARY a.target_namespace_sha256=BINARY NEW.target_namespace_sha256) AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0) AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.completed_at_ms IS NULL AND o.claim_token IS NOT NULL AND o.lease_until_ms>=v_now) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.completed_at_ms IS NULL AND o.claim_token IS NOT NULL AND o.lease_until_ms>=v_now) AND NOT EXISTS (SELECT 1 FROM user_export_download_leases l WHERE l.lease_until_ms>=v_now)) OR (OLD.phase NOT IN ('inactive','aborted','source_cleaned') AND NEW.control_generation=OLD.control_generation AND BINARY NEW.migration_id=BINARY OLD.migration_id AND BINARY NEW.source_backend=BINARY OLD.source_backend AND BINARY NEW.source_namespace_sha256=BINARY OLD.source_namespace_sha256 AND BINARY NEW.target_backend=BINARY OLD.target_backend AND BINARY NEW.target_namespace_sha256=BINARY OLD.target_namespace_sha256 AND NEW.rollback_window_ms=OLD.rollback_window_ms AND NEW.source_cleanup_delay_ms=OLD.source_cleanup_delay_ms AND NEW.cutover_not_before_db_ms=OLD.cutover_not_before_db_ms AND NEW.started_at_db_ms=OLD.started_at_db_ms AND BINARY NEW.fleet_drained_evidence_sha256=BINARY OLD.fleet_drained_evidence_sha256 AND ((OLD.phase='cutting_over' AND NEW.phase='committed' AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='committed' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256 AND NEW.completed_at_db_ms=r.occurred_at_db_ms AND NEW.source_cleanup_not_before_db_ms=r.source_cleanup_not_before_db_ms)) OR (OLD.phase='abort_cleaning' AND NEW.phase='aborted' AND NEW.source_cleanup_not_before_db_ms IS NULL AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='aborted' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256 AND NEW.completed_at_db_ms=r.occurred_at_db_ms)) OR (OLD.phase='committed' AND NEW.phase='source_cleaned' AND NEW.completed_at_db_ms=OLD.completed_at_db_ms AND NEW.source_cleanup_not_before_db_ms=OLD.source_cleanup_not_before_db_ms AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE r.migration_id=OLD.migration_id AND r.receipt_kind='source_cleaned' AND BINARY r.receipt_sha256=BINARY NEW.terminal_receipt_sha256 AND r.source_cleanup_ack_count=NEW.source_cleanup_ack_count AND BINARY r.source_cleanup_ack_root_sha256=BINARY NEW.source_cleanup_ack_root_sha256)) OR (NOT ((OLD.phase='cutting_over' AND NEW.phase='committed') OR (OLD.phase='abort_cleaning' AND NEW.phase='aborted') OR (OLD.phase='committed' AND NEW.phase='source_cleaned')) AND NEW.source_cleanup_not_before_db_ms<=>OLD.source_cleanup_not_before_db_ms AND NEW.completed_at_db_ms<=>OLD.completed_at_db_ms AND NEW.terminal_receipt_sha256<=>OLD.terminal_receipt_sha256))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration control invariant is not permitted'; END IF; END;
CREATE TRIGGER trg_blob_mover_control_bu BEFORE UPDATE ON blob_storage_migration_control FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NOT (((OLD.phase IN ('inactive','aborted')) AND NEW.phase='frozen') OR (OLD.phase='frozen' AND NEW.phase='inventory_sealed' AND NEW.inventory_entry_count=(SELECT COUNT(*) FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id) AND NEW.inventory_root_sha256 IS NOT NULL AND NEW.inventory_sealed_at_db_ms>=OLD.started_at_db_ms AND NEW.inventory_sealed_at_db_ms<=v_now AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_objects b WHERE (b.state<>'deleted' OR EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.blob_id=b.blob_id AND o.completed_at_ms IS NULL)) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='blob_object' AND BINARY i.record_id=BINARY b.blob_id AND i.record_sub_id=b.deletion_generation AND i.record_aux_id=0)) AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o WHERE o.completed_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='blob_delete_intent' AND BINARY i.record_id=BINARY CAST(o.outbox_id AS CHAR) AND i.record_sub_id=o.generation AND i.record_aux_id=0)) AND NOT EXISTS (SELECT 1 FROM user_export_artifacts a WHERE a.state<>'deleted' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_artifact' AND BINARY i.record_id=BINARY a.artifact_id AND i.record_sub_id=a.build_generation AND i.record_aux_id=0)) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE (p.state<>'deleted' OR EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.artifact_id=p.artifact_id AND o.part_number=p.part_number AND o.completed_at_ms IS NULL)) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_part' AND BINARY i.record_id=BINARY p.artifact_id AND i.record_sub_id=p.part_number AND i.record_aux_id=p.build_generation)) AND NOT EXISTS (SELECT 1 FROM user_export_snapshot_blobs s WHERE s.released_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_snapshot_pin' AND BINARY i.record_id=BINARY s.request_id AND i.record_sub_id=s.build_generation AND i.record_aux_id=s.ordinal)) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.completed_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.record_kind='export_delete_intent' AND BINARY i.record_id=BINARY CAST(o.outbox_id AS CHAR) AND i.record_sub_id=o.deletion_generation AND i.record_aux_id=o.part_number)) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i JOIN blob_storage_migration_inventory j ON j.migration_id=i.migration_id AND BINARY j.storage_key=BINARY i.storage_key AND j.entry_ordinal<>i.entry_ordinal WHERE i.migration_id=OLD.migration_id AND i.storage_key IS NOT NULL AND (NOT (BINARY i.object_disposition=BINARY j.object_disposition) OR NOT (i.expected_sha256<=>j.expected_sha256) OR NOT (i.expected_size_bytes<=>j.expected_size_bytes) OR NOT (i.expected_content_type<=>j.expected_content_type)))) OR (OLD.phase='inventory_sealed' AND NEW.phase='copying' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=0 AND NEW.object_ack_root_sha256 IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms IS NULL) OR (OLD.phase='copying' AND NEW.phase='verified' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_object_acks a WHERE a.migration_id=OLD.migration_id) AND NEW.object_ack_root_sha256 IS NOT NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms>=OLD.inventory_sealed_at_db_ms AND NEW.verified_at_db_ms<=v_now AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id AND i.object_disposition<>'metadata' AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE a.migration_id=i.migration_id AND BINARY a.storage_key=BINARY i.storage_key AND BINARY a.object_disposition=BINARY i.object_disposition AND BINARY a.target_backend=BINARY i.target_backend AND BINARY a.target_namespace_sha256=BINARY i.target_namespace_sha256 AND a.expected_sha256<=>i.expected_sha256 AND a.expected_size_bytes<=>i.expected_size_bytes AND a.expected_content_type<=>i.expected_content_type)) OR (OLD.phase IN ('frozen','inventory_sealed','copying','verified') AND NEW.phase='abort_cleaning' AND NEW.inventory_entry_count=(SELECT COUNT(*) FROM blob_storage_migration_inventory i WHERE i.migration_id=OLD.migration_id) AND NEW.inventory_root_sha256 IS NOT NULL AND NEW.inventory_sealed_at_db_ms=COALESCE(OLD.inventory_sealed_at_db_ms,NEW.inventory_sealed_at_db_ms) AND NEW.inventory_sealed_at_db_ms>=OLD.started_at_db_ms AND NEW.inventory_sealed_at_db_ms<=v_now AND NEW.object_ack_count=(SELECT COUNT(*) FROM blob_stora