ob_storage_migration_object_acks a WHERE a.migration_id=OLD.migration_id) AND NEW.object_ack_root_sha256 IS NOT NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms<=>OLD.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (OLD.phase='verified' AND NEW.phase='cutting_over' AND v_now>=OLD.cutover_not_before_db_ms AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms=OLD.verified_at_db_ms) OR (OLD.phase='cutting_over' AND NEW.phase='committed' AND NEW.inventory_entry_count=OLD.inventory_entry_count AND BINARY NEW.inventory_root_sha256=BINARY OLD.inventory_root_sha256 AND NEW.inventory_sealed_at_db_ms=OLD.inventory_sealed_at_db_ms AND NEW.object_ack_count=OLD.object_ack_count AND BINARY NEW.object_ack_root_sha256=BINARY OLD.object_ack_root_sha256 AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.verified_at_db_ms=OLD.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_migration_receipts r JOIN blob_storage_control b ON b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY OLD.target_backend AND BINARY b.namespace_sha256=BINARY OLD.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY r.blob_control_evidence_sha256 WHERE r.migration_id=OLD.migration_id AND r.receipt_kind