-- Final receipt guards bind source cleanup to the still-committed migration projection and the
-- exact active generation-1 Blob control. They are restated here so marker-loss replay converges
-- even when an older auto-commit boundary installed the earlier guard bodies.
DROP TRIGGER IF EXISTS trg_blob_mover_receipts_bi_guard_a;
DROP TRIGGER IF EXISTS trg_blob_mover_receipts_bi;
CREATE TRIGGER trg_blob_mover_receipts_bi_guard_a BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.occurred_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.rollback_window_ms=NEW.rollback_window_ms AND c.source_cleanup_delay_ms=NEW.source_cleanup_delay_ms AND c.cutover_not_before_db_ms=NEW.cutover_not_before_db_ms AND BINARY c.fleet_drained_evidence_sha256=BINARY NEW.fleet_drained_evidence_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND NEW.source_cleanup_not_before_db_ms=NEW.occurred_at_db_ms+NEW.source_cleanup_delay_ms AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_target_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.target_cleanup_ack_root_sha256 IS NOT NULL AND NEW.occurred_at_db_ms>=c.inventory_sealed_at_db_ms AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.source_cleanup_not_before_db_ms=c.source_cleanup_not_before_db_ms AND NEW.source_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.source_cleanup_ack_root_sha256 IS NOT NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.source_cleanup_not_before_db_ms AND NEW.blob_control_evidence_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;
CREATE TRIGGER trg_blob_mover_receipts_bi BEFORE INSERT ON blob_storage_migration_receipts FOR EACH ROW BEGIN DECLARE v_now BIGINT UNSIGNED DEFAULT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED); IF NEW.occurred_at_db_ms>v_now OR NOT EXISTS (SELECT 1 FROM blob_storage_migration_control c WHERE c.singleton_id=1 AND BINARY c.migration_id=BINARY NEW.migration_id AND c.control_generation=NEW.control_generation AND BINARY c.source_backend=BINARY NEW.source_backend AND BINARY c.source_namespace_sha256=BINARY NEW.source_namespace_sha256 AND BINARY c.target_backend=BINARY NEW.target_backend AND BINARY c.target_namespace_sha256=BINARY NEW.target_namespace_sha256 AND c.rollback_window_ms=NEW.rollback_window_ms AND c.source_cleanup_delay_ms=NEW.source_cleanup_delay_ms AND c.cutover_not_before_db_ms=NEW.cutover_not_before_db_ms AND BINARY c.fleet_drained_evidence_sha256=BINARY NEW.fleet_drained_evidence_sha256 AND c.inventory_entry_count=NEW.inventory_entry_count AND BINARY c.inventory_root_sha256=BINARY NEW.inventory_root_sha256 AND c.object_ack_count=NEW.object_ack_count AND BINARY c.object_ack_root_sha256=BINARY NEW.object_ack_root_sha256 AND ((NEW.receipt_kind='committed' AND c.phase='cutting_over' AND NEW.source_cleanup_not_before_db_ms=NEW.occurred_at_db_ms+NEW.source_cleanup_delay_ms AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.verified_at_db_ms AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)) OR (NEW.receipt_kind='aborted' AND c.phase='abort_cleaning' AND NEW.source_cleanup_not_before_db_ms IS NULL AND NEW.source_cleanup_ack_count=0 AND NEW.source_cleanup_ack_root_sha256 IS NULL AND NEW.target_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_target_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.target_cleanup_ack_root_sha256 IS NOT NULL AND NEW.occurred_at_db_ms>=c.inventory_sealed_at_db_ms AND NEW.blob_control_evidence_sha256 IS NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=0)) OR (NEW.receipt_kind='source_cleaned' AND c.phase='committed' AND NEW.source_cleanup_not_before_db_ms=c.source_cleanup_not_before_db_ms AND NEW.source_cleanup_ack_count=(SELECT COUNT(*) FROM blob_storage_migration_source_cleanup_acks a WHERE a.migration_id=c.migration_id) AND NEW.source_cleanup_ack_root_sha256 IS NOT NULL AND NEW.target_cleanup_ack_count=0 AND NEW.target_cleanup_ack_root_sha256 IS NULL AND NEW.occurred_at_db_ms>=c.source_cleanup_not_before_db_ms AND NEW.blob_control_evidence_sha256 IS NOT NULL AND EXISTS (SELECT 1 FROM blob_storage_control b WHERE b.singleton_id=1 AND b.control_generation=1 AND BINARY b.storage_backend=BINARY c.target_backend AND BINARY b.namespace_sha256=BINARY c.target_namespace_sha256 AND BINARY b.evidence_sha256=BINARY NEW.blob_control_evidence_sha256)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob migration receipt is not control-bound'; END IF; END;

-- Serialize ordinary generation-1 activation with the mover's migration-control -> Blob-control
-- lock order. The exact cutting_over target is the only migration-owned activation; otherwise the
-- mover must be dormant/aborted and the namespace must never have appeared in any durable attempt.
-- Replace all three 0027 duplicates so direct SQL and marker-loss replay retain the same authority.
DROP TRIGGER IF EXISTS trg_blob_storage_control_bu_bootstrap;
CREATE TRIGGER trg_blob_storage_control_bu_bootstrap BEFORE UPDATE ON blob_storage_control FOR EACH ROW BEGIN IF NOT (OLD.singleton_id=1 AND NEW.singleton_id=1 AND OLD.control_generation=0 AND OLD.storage_backend IS NULL AND OLD.namespace_sha256 IS NULL AND OLD.activated_at_db_ms IS NULL AND OLD.evidence_sha256 IS NULL AND NEW.control_generation=1 AND NEW.storage_backend REGEXP '^[a-z0-9][a-z0-9._-]{0,31}$' AND NEW.namespace_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.activated_at_db_ms IS NOT NULL AND NEW.activated_at_db_ms>=0 AND NEW.evidence_sha256 REGEXP '^[0-9a-f]{64}$' AND NOT EXISTS (SELECT 1 FROM blob_objects b WHERE b.state<>'deleted' AND NOT (BINARY b.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM user_export_artifacts a WHERE a.state<>'deleted' AND NOT (BINARY a.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE p.state<>'deleted' AND NOT (BINARY p.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o LEFT JOIN blob_objects b ON b.blob_id=o.blob_id WHERE o.completed_at_ms IS NULL AND o.dead_lettered_at_ms IS NULL AND (b.blob_id IS NULL OR NOT (BINARY b.storage_backend=BINARY NEW.storage_backend))) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.completed_at_ms IS NULL AND o.dead_lettered_at_ms IS NULL AND NOT (BINARY o.storage_backend=BINARY NEW.storage_backend)) AND (EXISTS (SELECT 1 FROM blob_storage_migration_control m WHERE m.singleton_id=1 AND m.phase='cutting_over' AND BINARY m.target_backend=BINARY NEW.storage_backend AND BINARY m.target_namespace_sha256=BINARY NEW.namespace_sha256) OR (EXISTS (SELECT 1 FROM blob_storage_migration_control m WHERE m.singleton_id=1 AND m.phase IN ('inactive','aborted') AND (m.target_namespace_sha256 IS NULL OR NOT (BINARY m.target_namespace_sha256=BINARY NEW.namespace_sha256))) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE BINARY i.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE BINARY a.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE BINARY r.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_target_cleanup_acks a WHERE BINARY a.target_namespace_sha256=BINARY NEW.namespace_sha256)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob storage control is write-once or inventory conflicts'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_storage_control_bu;
CREATE TRIGGER trg_blob_storage_control_bu BEFORE UPDATE ON blob_storage_control FOR EACH ROW BEGIN IF NOT (OLD.singleton_id=1 AND NEW.singleton_id=1 AND OLD.control_generation=0 AND OLD.storage_backend IS NULL AND OLD.namespace_sha256 IS NULL AND OLD.activated_at_db_ms IS NULL AND OLD.evidence_sha256 IS NULL AND NEW.control_generation=1 AND NEW.storage_backend REGEXP '^[a-z0-9][a-z0-9._-]{0,31}$' AND NEW.namespace_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.activated_at_db_ms IS NOT NULL AND NEW.activated_at_db_ms>=0 AND NEW.evidence_sha256 REGEXP '^[0-9a-f]{64}$' AND NOT EXISTS (SELECT 1 FROM blob_objects b WHERE b.state<>'deleted' AND NOT (BINARY b.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM user_export_artifacts a WHERE a.state<>'deleted' AND NOT (BINARY a.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE p.state<>'deleted' AND NOT (BINARY p.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o LEFT JOIN blob_objects b ON b.blob_id=o.blob_id WHERE o.completed_at_ms IS NULL AND o.dead_lettered_at_ms IS NULL AND (b.blob_id IS NULL OR NOT (BINARY b.storage_backend=BINARY NEW.storage_backend))) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.completed_at_ms IS NULL AND o.dead_lettered_at_ms IS NULL AND NOT (BINARY o.storage_backend=BINARY NEW.storage_backend)) AND (EXISTS (SELECT 1 FROM blob_storage_migration_control m WHERE m.singleton_id=1 AND m.phase='cutting_over' AND BINARY m.target_backend=BINARY NEW.storage_backend AND BINARY m.target_namespace_sha256=BINARY NEW.namespace_sha256) OR (EXISTS (SELECT 1 FROM blob_storage_migration_control m WHERE m.singleton_id=1 AND m.phase IN ('inactive','aborted') AND (m.target_namespace_sha256 IS NULL OR NOT (BINARY m.target_namespace_sha256=BINARY NEW.namespace_sha256))) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE BINARY i.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE BINARY a.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE BINARY r.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_target_cleanup_acks a WHERE BINARY a.target_namespace_sha256=BINARY NEW.namespace_sha256)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob storage control is write-once or inventory conflicts'; END IF; END;
DROP TRIGGER IF EXISTS trg_blob_storage_control_bu_guard_a;
CREATE TRIGGER trg_blob_storage_control_bu_guard_a BEFORE UPDATE ON blob_storage_control FOR EACH ROW BEGIN IF NOT (OLD.singleton_id=1 AND NEW.singleton_id=1 AND OLD.control_generation=0 AND OLD.storage_backend IS NULL AND OLD.namespace_sha256 IS NULL AND OLD.activated_at_db_ms IS NULL AND OLD.evidence_sha256 IS NULL AND NEW.control_generation=1 AND NEW.storage_backend REGEXP '^[a-z0-9][a-z0-9._-]{0,31}$' AND NEW.namespace_sha256 REGEXP '^[0-9a-f]{64}$' AND NEW.activated_at_db_ms IS NOT NULL AND NEW.activated_at_db_ms>=0 AND NEW.evidence_sha256 REGEXP '^[0-9a-f]{64}$' AND NOT EXISTS (SELECT 1 FROM blob_objects b WHERE b.state<>'deleted' AND NOT (BINARY b.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM user_export_artifacts a WHERE a.state<>'deleted' AND NOT (BINARY a.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_parts p WHERE p.state<>'deleted' AND NOT (BINARY p.storage_backend=BINARY NEW.storage_backend)) AND NOT EXISTS (SELECT 1 FROM blob_delete_outbox o LEFT JOIN blob_objects b ON b.blob_id=o.blob_id WHERE o.completed_at_ms IS NULL AND o.dead_lettered_at_ms IS NULL AND (b.blob_id IS NULL OR NOT (BINARY b.storage_backend=BINARY NEW.storage_backend))) AND NOT EXISTS (SELECT 1 FROM user_export_artifact_delete_outbox o WHERE o.completed_at_ms IS NULL AND o.dead_lettered_at_ms IS NULL AND NOT (BINARY o.storage_backend=BINARY NEW.storage_backend)) AND (EXISTS (SELECT 1 FROM blob_storage_migration_control m WHERE m.singleton_id=1 AND m.phase='cutting_over' AND BINARY m.target_backend=BINARY NEW.storage_backend AND BINARY m.target_namespace_sha256=BINARY NEW.namespace_sha256) OR (EXISTS (SELECT 1 FROM blob_storage_migration_control m WHERE m.singleton_id=1 AND m.phase IN ('inactive','aborted') AND (m.target_namespace_sha256 IS NULL OR NOT (BINARY m.target_namespace_sha256=BINARY NEW.namespace_sha256))) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_inventory i WHERE BINARY i.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_object_acks a WHERE BINARY a.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_receipts r WHERE BINARY r.target_namespace_sha256=BINARY NEW.namespace_sha256) AND NOT EXISTS (SELECT 1 FROM blob_storage_migration_target_cleanup_acks a WHERE BINARY a.target_namespace_sha256=BINARY NEW.namespace_sha256)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='blob storage control is write-once or inventory conflicts'; END IF; END;

-- CREATE TABLE IF NOT EXISTS is not a schema verifier. Marker-loss replay and every DDL
-- auto-commit boundary must fail closed on a weaker same-name table, index, CHECK, constraint,
-- partition, missing/extra migration trigger, or trigger-body drift.
SET @blob_migration_previous_group_concat_max_len = @@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len = 1048576;
SET @blob_migration_schema_ok = (
  (SELECT COUNT(*) = 7
       AND SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,table_type,
             IFNULL(engine,'-'),IFNULL(table_collation,'-'))
           ORDER BY table_name SEPARATOR '|'),256)
         = 'e55fa3878895767331dee6e4f1674b1f95a5ada8ea5286461b6027d149a02489'
     FROM information_schema.tables
    WHERE table_schema=DATABASE() AND table_name IN (
      'blob_storage_migration_control','blob_storage_migration_inventory',
      'blob_storage_migration_object_acks','blob_storage_migration_events',
      'blob_storage_migration_receipts','blob_storage_migration_source_cleanup_acks',
      'blob_storage_migration_target_cleanup_acks'))
  AND
  (SELECT COUNT(*) = 117
       AND SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,LPAD(ordinal_position,3,'0'),
             column_name,LOWER(column_type),is_nullable,
             IF(column_default IS NULL,'<NULL>',CONCAT('<',column_default,'>')),
             IFNULL(character_set_name,'-'),IFNULL(collation_name,'-'),
             IFNULL(NULLIF(LOWER(extra),''),'-'),
             IFNULL(NULLIF(LOWER(generation_expression),''),'-'))
           ORDER BY table_name,ordinal_position SEPARATOR '|'),256)
         = 'b902d31a0e6ecec658e8d1cb024b7e3fd8b89a511d96ec1e502e8e15044a5f91'
     FROM information_schema.columns
    WHERE table_schema=DATABASE() AND table_name IN (
      'blob_storage_migration_control','blob_storage_migration_inventory',
      'blob_storage_migration_object_acks','blob_storage_migration_events',
      'blob_storage_migration_receipts','blob_storage_migration_source_cleanup_acks',
      'blob_storage_migration_target_cleanup_acks'))
  AND
  (SELECT COUNT(DISTINCT CONCAT(table_name,'~',index_name)) = 14 AND COUNT(*) = 31
       AND SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,index_name,non_unique,
             seq_in_index,LOWER(index_type),LOWER(is_visible),
             IFNULL(column_name,'<expression>'),IFNULL(CAST(sub_part AS CHAR),'-'),
             LOWER(IFNULL(collation,'-')),IFNULL(expression,'-'))
           ORDER BY table_name,index_name,seq_in_index SEPARATOR '|'),256)
         = 'c79da7b407ff5e7b883ed3b328cd0235138524a4a4eea3b7be7cd8d3e1c26193'
     FROM information_schema.statistics
    WHERE table_schema=DATABASE() AND table_name IN (
      'blob_storage_migration_control','blob_storage_migration_inventory',
      'blob_storage_migration_object_acks','blob_storage_migration_events',
      'blob_storage_migration_receipts','blob_storage_migration_source_cleanup_acks',
      'blob_storage_migration_target_cleanup_acks'))
  AND
  (SELECT COUNT(*) = 13
       AND SHA2(GROUP_CONCAT(CONCAT_WS('~',tc.table_name,tc.constraint_name,tc.enforced,
             LOWER(REPLACE(REPLACE(REGEXP_REPLACE(cc.check_clause,'[[:space:]]',''),
               CHAR(96),''),'_utf8mb4','')))
           ORDER BY tc.table_name,tc.constraint_name SEPARATOR '|'),256)
         = '2cc88f652bf3cb11839abcfcaffc2b769a22a674dd9ccec6f66d6c03c2e3a39a'
     FROM information_schema.table_constraints tc
     JOIN information_schema.check_constraints cc
       ON cc.constraint_schema=tc.constraint_schema
      AND cc.constraint_name=tc.constraint_name
    WHERE tc.table_schema=DATABASE() AND tc.constraint_type='CHECK'
      AND tc.table_name IN (
        'blob_storage_migration_control','blob_storage_migration_inventory',
        'blob_storage_migration_object_acks','blob_storage_migration_events',
        'blob_storage_migration_receipts','blob_storage_migration_source_cleanup_acks',
        'blob_storage_migration_target_cleanup_acks'))
  AND
  (SELECT COUNT(*) = 26
       AND SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,
             constraint_type,enforced)
           ORDER BY table_name,constraint_name SEPARATOR '|'),256)
         = '15871490773dc5e95c31cfdffeb7c3b55eee15ed32235886491c652c280fd6ef'
     FROM information_schema.table_constraints
    WHERE table_schema=DATABASE() AND table_name IN (
      'blob_storage_migration_control','blob_storage_migration_inventory',
      'blob_storage_migration_object_acks','blob_storage_migration_events',
      'blob_storage_migration_receipts','blob_storage_migration_source_cleanup_acks',
      'blob_storage_migration_target_cleanup_acks'))
  AND NOT EXISTS (
    SELECT 1 FROM information_schema.partitions
     WHERE table_schema=DATABASE() AND partition_name IS NOT NULL
       AND table_name IN (
         'blob_storage_migration_control','blob_storage_migration_inventory',
         'blob_storage_migration_object_acks','blob_storage_migration_events',
         'blob_storage_migration_receipts','blob_storage_migration_source_cleanup_acks',
         'blob_storage_migration_target_cleanup_acks'))
);
SET @migration_sql = IF(@blob_migration_schema_ok=1, 'SELECT 1',
  'SELECT 1 FROM __invalid_blob_storage_migration_schema__');
PREPARE migration_stmt FROM @migration_sql;
EXECUTE migration_stmt;
DEALLOCATE PREPARE migration_stmt;

SET @blob_migration_trigger_set_ok = (
  SELECT COUNT(*)=89 AND COUNT(DISTINCT trigger_name)=89
     AND SHA2(GROUP_CONCAT(CONCAT_WS('~',event_object_table,trigger_name,
           LPAD(action_order,3,'0'),action_timing,event_manipulation,action_orientation,
           IFNULL(action_condition,'<NULL>'),
           LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),
             CHAR(96),''),'_utf8mb4','')))
         ORDER BY event_object_table,trigger_name SEPARATOR '|'),256)
       = '8d8621bb8a89cf145b3767a62fe8d233a6f49b4cb6ec2968627c35e1cf4667a1'
    FROM information_schema.triggers
   WHERE trigger_schema=DATABASE() AND (
     trigger_name LIKE 'trg_blob_mover_%'
     OR trigger_name IN (
       'trg_blob_storage_object_bu_guard_a','trg_blob_storage_object_bu',
       'trg_blob_storage_export_artifact_bu_guard_a','trg_blob_storage_export_artifact_bu',
       'trg_blob_storage_export_part_bu_guard_a','trg_blob_storage_export_part_bu',
       'trg_blob_storage_snapshot_bu_guard_a','trg_blob_storage_snapshot_bu',
       'trg_blob_storage_export_outbox_bu_guard_a','trg_blob_storage_export_outbox_bu',
       'trg_blob_storage_control_bu_bootstrap','trg_blob_storage_control_bu',
       'trg_blob_storage_control_bu_guard_a'))
);
SET @migration_sql = IF(@blob_migration_trigger_set_ok=1, 'SELECT 1',
  'SELECT 1 FROM __invalid_blob_storage_migration_trigger_set__');
PREPARE migration_stmt FROM @migration_sql;
EXECUTE migration_stmt;
DEALLOCATE PREPARE migration_stmt;
SET SESSION group_concat_max_len = @blob_migration_previous_group_concat_max_len;
